  }

  enumerateMoves(actorRole: RuntimeActorRole = "player"): RuntimeLegalMove<MoveRecord>[] {
    const playerId = this.state.ctx.priority.holder ?? this.state.ctx.playerIds[0];
    if (!playerId) {
