      this.nextGameEventSeq = snapshot.nextGameEventSeq;
    }
    this.gameEnded = snapshot.gameEnded;
    this.gameEndResult = snapshot.gameEndResult;
  }

  appendSyntheticCommand(
    command: CommandEnvelope,
    playerId: string,
    timestamp: number,
  ): {
    gameEvents: PublishedGameEvent[];
