  }

  getRuntimeCardCacheStats() {
    return getStateScopedValueCacheStats(this.runtimeCardCache);
  }

  private publishGameEvents(
    gameEvents: GameEvent[],
    stateId: number,
    timestamp: number,
  ): PublishedGameEvent[] {
    return gameEvents.map((event) => ({
      seq: this.nextGameEventSeq++,
      timestamp,
      stateId,
      event,
    }));
  }
}

