    const timedPlayerState = playerState as ChessClockPlayerState | DynamicClockPlayerState;
    summary.isInNegativeTime = timedPlayerState.isInNegativeTime;
    summary.timeoutCount = timedPlayerState.timeoutCount;
  }

  return summary;
}

