    }

    const legalMoveIds = this.engine.enumerateMoves() as Array<
      keyof LorcanaRuntimeMoveInputs & string
    >;
    this._cachedLegalMoveIds = legalMoveIds;
    this._cachedLegalMoveIdsStateID = currentStateID;
    return legalMoveIds;
  }

