  protected executeManualMoveForActingPlayer<K extends keyof LorcanaRuntimeMoveParams & string>(
    moveId: K,
    params: LorcanaRuntimeMoveParams[K],
    options: { playerPreference?: ManualActingPlayerPreference } = {},
