  private getPlayerZoneCardIdsForMoveOptions(
    playerId: string,
    zone: "discard" | "hand" | "play",
  ): CardInstanceId[] {
    const playerBoard = this.getBoard().players[playerId];
    if (!playerBoard) {
      return [];
    }

    const zoneCards =
      zone === "discard"
        ? playerBoard.discard
        : zone === "hand"
          ? playerBoard.hand
          : playerBoard.play;

    return zoneCards.map((id) => id as CardInstanceId);
  }

  private matchesDiscardSelectableCostRequirements(
    definition: LorcanaCardDefinition | undefined,
    cost: {
      discardCardType?: string;
      discardCardName?: string;
    },
  ): boolean {
    if (!definition) {
      return false;
    }

    if (cost.discardCardType === "song") {
      if (definition.cardType !== "action" || !isSongCard(definition as LorcanaCard)) {
        return false;
      }
    } else if (cost.discardCardType && definition.cardType !== cost.discardCardType) {
      return false;
    }

    if (
      cost.discardCardName &&
      !cardHasName(definition as LorcanaCardDefinition, cost.discardCardName)
    ) {
      return false;
    }

    return true;
  }

  private getSelectableCostsForActivatedAbility(
    playerId: string,
    sourceCardId: CardInstanceId,
    ability: AbilityDefinition,
  ): MoveOptionSelectableCost[] {
    if (ability.type !== "activated") {
      return [];
    }

    const playableCards = this.getPlayerZoneCardIdsForMoveOptions(playerId, "play");
    const handCards = this.getPlayerZoneCardIdsForMoveOptions(playerId, "hand");
    const selectableCosts: MoveOptionSelectableCost[] = [];
    const revealCount = Math.max(0, Math.floor(ability.cost?.revealCards ?? 0));
    if (revealCount > 0) {
      const candidateGroups = getRevealCardCostCandidateGroups(
        handCards,
        revealCount,
        ability.cost?.revealSameName === true,
        (id) => this.getCardDefinitionByInstanceId(id).name,
      );
      selectableCosts.push({
        kind: "revealCards",
        count: revealCount,
        candidateCardIds: [...new Set(candidateGroups.flat())],
        zone: "hand",
        ...(ability.cost?.revealSameName ? { candidateGroups } : {}),
      });
    }

    const discardCount =
      typeof ability.cost?.discardCards === "number"
        ? Math.max(0, Math.floor(ability.cost.discardCards))
        : typeof ability.cost?.discardCard === "number"
          ? Math.max(0, Math.floor(ability.cost.discardCard))
          : typeof ability.cost?.discard === "object" &&
              typeof ability.cost.discard.amount === "number"
            ? Math.max(0, Math.floor(ability.cost.discard.amount))
            : 0;

    if (discardCount > 0) {
      const discardCardType =
        ability.cost?.discardCardType ??
        (typeof ability.cost?.discard === "object" ? ability.cost.discard.cardType : undefined);
      const discardCardName = ability.cost?.discardCardName;
      const candidateCardIds = handCards.filter((cardId) =>
        this.matchesDiscardSelectableCostRequirements(this.getCardDefinitionByInstanceId(cardId), {
          discardCardType,
          discardCardName,
        }),
      );

      selectableCosts.push({
        kind: "discardCards",
        count: discardCount,
        candidateCardIds,
        zone: "hand",
        ...(discardCardType ? { cardType: discardCardType } : {}),
        ...(discardCardName ? { cardName: discardCardName } : {}),
      });
    }

    const exertCharacterCount =
      typeof ability.cost?.exertCharacters === "number"
        ? Math.max(0, Math.floor(ability.cost.exertCharacters))
        : ability.cost?.exertCharacter
          ? 1
          : 0;
    if (exertCharacterCount > 0) {
      const classification = ability.cost?.exertCharactersClassification;
      const candidateCardIds = playableCards.filter((cardId) => {
        if (ability.cost?.exert === true && cardId === sourceCardId) {
          return false;
        }

        const definition = this.getCardDefinitionByInstanceId(cardId);
        if (!definition || definition.cardType !== "character") {
          return false;
        }

        if (classification) {
          const classifications =
            (definition as { classifications?: string[] }).classifications ?? [];
          if (!classifications.includes(classification)) {
            return false;
          }
        }

        return !this.isExerted(cardId) && !this.isDrying(cardId);
      });

      selectableCosts.push({
        kind: "exertCharacters",
        count: exertCharacterCount,
        candidateCardIds,
        zone: "play",
        cardType: "character",
        ...(classification ? { classification } : {}),
      });
    }

    const exertItemCount =
      typeof ability.cost?.exertItems === "number"
        ? Math.max(0, Math.floor(ability.cost.exertItems))
        : 0;
    if (exertItemCount > 0) {
      const candidateCardIds = playableCards.filter((cardId) => {
        const definition = this.getCardDefinitionByInstanceId(cardId);
        return definition?.cardType === "item" && !this.isExerted(cardId);
      });
      selectableCosts.push({
        kind: "exertItems",
        count: exertItemCount,
        candidateCardIds,
        zone: "play",
        cardType: "item",
      });
    }

    const banishCharacterCount = ability.cost?.banishCharacter ? 1 : 0;
    if (banishCharacterCount > 0) {
      const validationContext = buildValidationContext({
        state: this.getState() as LorcanaMatchState,
        playerId,
        input: { args: {} } as LorcanaRuntimeMoveInputs["passTurn"],
        config: lorcanaRuntimeConfig as unknown as MatchRuntimeConfig,
        staticResources: this.getResolvedStaticResources(),
        gameEnded: !!this.getState().ctx.status.gameEnded,
        validationMode: "preflight",
      });
      const candidateCardIds = getBanishCharacterCostCandidateIds(
        validationContext,
        playerId as PlayerId,
        ability as ActivatedAbilityDefinition,
        sourceCardId,
      );
      selectableCosts.push({
        kind: "banishCharacters",
        count: banishCharacterCount,
        candidateCardIds,
        zone: "play",
        cardType: "character",
      });
    }

    const banishItemCount =
      typeof ability.cost?.banishItem === "number"
        ? Math.max(0, Math.floor(ability.cost.banishItem))
        : ability.cost?.banishItem
          ? 1
          : 0;
    if (banishItemCount > 0) {
      const candidateCardIds = playableCards.filter(
        (cardId) =>
          this.getCardDefinitionByInstanceId(cardId)?.cardType === "item" &&
          !(ability.cost?.banishItemTarget === "another" && cardId === sourceCardId),
      );
      selectableCosts.push({
        kind: "banishItems",
        count: banishItemCount,
        candidateCardIds,
        zone: "play",
        cardType: "item",
      });
    }

    return selectableCosts;
  }

  private getSelectableCostsForShift(
    playerId: string,
    cardDef: LorcanaCard,
  ): MoveOptionSelectableCost[] {
    const shiftRules = getShiftRules(cardDef);
    if (shiftRules?.discardCost) {
      const handCards = this.getPlayerZoneCardIdsForMoveOptions(playerId, "hand");
      const candidateCardIds = handCards.filter((cardId) =>
        this.matchesDiscardSelectableCostRequirements(this.getCardDefinitionByInstanceId(cardId), {
          discardCardType: shiftRules.discardCost?.discardCardType,
        }),
      );

      return [
        {
          kind: "discardCards",
          count: shiftRules.discardCost.discardCards,
          candidateCardIds,
          zone: "hand",
          ...(shiftRules.discardCost.discardCardType
            ? { cardType: shiftRules.discardCost.discardCardType }
            : {}),
        },
      ];
    }

    const hasDeckBottomShiftAlternativeCost = cardDef.abilities?.some(
      (ability) =>
        ability.type === "action" &&
        "alternativeCost" in ability &&
        ability.alternativeCost === "put-5-character-cards-on-deck-bottom-to-shift",
    );
    if (!hasDeckBottomShiftAlternativeCost) {
      return [];
    }

    const discardCards = this.getPlayerZoneCardIdsForMoveOptions(playerId, "discard");
    const candidateCardIds = discardCards.filter(
      (cardId) => this.getCardDefinitionByInstanceId(cardId)?.cardType === "character",
    );

    return [
      {
        kind: "putOnDeckBottom",
        count: 5,
        candidateCardIds,
        zone: "discard",
        cardType: "character",
      },
    ];
  }

  private hasSufficientSelectableCosts(
    selectableCosts: readonly MoveOptionSelectableCost[],
  ): boolean {
    return selectableCosts.every((cost) => cost.candidateCardIds.length >= cost.count);
  }

  private canDiscoverShiftPlay(
    cardId: CardInstanceId,
    shiftTarget: CardInstanceId,
    selectableCosts: readonly MoveOptionSelectableCost[] = [],
    inkDrops?: number,
  ): boolean {
    return this.canDiscoverShiftPlayGroup(cardId, [shiftTarget], selectableCosts, inkDrops);
  }

  private canDiscoverShiftPlayGroup(
    cardId: CardInstanceId,
    shiftTargets: readonly CardInstanceId[],
    selectableCosts: readonly MoveOptionSelectableCost[] = [],
    inkDrops?: number,
  ): boolean {
    const [shiftTarget, ...additionalShiftTargets] = shiftTargets;
    if (!shiftTarget) {
      return false;
    }

    const usesDeckBottomShiftCost = selectableCosts.some((cost) => cost.kind === "putOnDeckBottom");
    const validation = this.validateMove("playCard", {
      args: {
        cardId,
        cost: "shift",
        shiftTarget,
        inkDrops: inkDrops ?? 0,
        ...(additionalShiftTargets.length > 0 ? { additionalShiftTargets } : {}),
        ...(usesDeckBottomShiftCost ? { deckBottomTargets: [] } : {}),
      },
    });

    return (
      validation.valid ||
      validation.code === "SHIFT_DISCARD_REQUIRED" ||
      (usesDeckBottomShiftCost && validation.code === "INVALID_DECK_BOTTOM_SHIFT_TARGET_COUNT")
    );
  }

  private selectDiscoverableShiftTargetGroup(
    cardId: CardInstanceId,
    shiftRules: NonNullable<ReturnType<typeof getShiftRules>>,
    shiftTargets: readonly CardInstanceId[],
    selectableCosts: readonly MoveOptionSelectableCost[] = [],
    inkDrops?: number,
  ): CardInstanceId[] | null {
    if (!shiftRules.multiShift) {
      const target = shiftTargets.find((targetId) =>
        this.canDiscoverShiftPlay(cardId, targetId, selectableCosts, inkDrops),
      );
      return target ? [target] : null;
    }

    const { minTargets, maxTargets } = shiftRules.multiShift;
    const maxGroupSize = Math.min(maxTargets, shiftTargets.length);
    if (maxGroupSize < minTargets) {
      return null;
    }

    const selected: CardInstanceId[] = [];
    const findGroup = (startIndex: number, targetSize: number): CardInstanceId[] | null => {
      if (selected.length === targetSize) {
        return this.canDiscoverShiftPlayGroup(cardId, selected, selectableCosts, inkDrops)
          ? [...selected]
          : null;
      }

      const remainingSelections = targetSize - selected.length;
      for (let index = startIndex; index <= shiftTargets.length - remainingSelections; index += 1) {
        selected.push(shiftTargets[index]);
        const group = findGroup(index + 1, targetSize);
        selected.pop();
        if (group) {
          return group;
        }
      }

      return null;
    };

    for (let targetSize = minTargets; targetSize <= maxGroupSize; targetSize += 1) {
      const group = findGroup(0, targetSize);
      if (group) {
        return group;
      }
    }

    return null;
  }

