  canUndo(playerId?: string): boolean {
    const resolvedPlayerId =
      playerId ?? this.getScopedPlayerId() ?? String(this.getActivePlayer() ?? "");
    if (!resolvedPlayerId) {
      return false;
    }

    return this.engine.canUndo?.(resolvedPlayerId) ?? false;
