          ...result,
          fallbackTaken: "concede",
          finalResult: concedeResult,
        };
      }
    }

    if (latestTrace) {
      options.traceSink?.push({
        ...latestTrace,
        ...(result.blocked ? { blocked: result.blocked } : {}),
        ...(result.fallbackTaken ? { fallbackTaken: result.fallbackTaken } : {}),
