      ctx.framework.zones.moveCard(
        cardId,
        {
          zone: "deck",
          playerId: ownerId,
        },
        {
          index: 0,
        },
      );
      ctx.cards.patchMeta(cardId, {
        stackParentId: undefined,
        state: undefined,
        publicFaceState: undefined,
      });
  }
