import {
  createPendingActionEffect,
  enqueuePendingActionEffect,
} from "../../resolution/action-effects/pending-action-effects";

type PassTurnExecutionContext = Pick<
  MoveExecutionContext<LorcanaRuntimeMoveInputs["passTurn"]>,
  "G" | "playerId" | "query" | "framework" | "cards"
>;

type PassTurnValidationContext = MoveValidationContext<LorcanaRuntimeMoveInputs["passTurn"]>;

type PassTurnEnumerationContext = MoveEnumerationContext;

type PassTurnIntentContext = PassTurnValidationContext | PassTurnEnumerationContext;

type PassTurnFailure = Extract<RuntimeValidationResult, { valid: false }>;

export const PASS_TURN_STACK_PENDING_ERROR_CODE = "PASS_TURN_STACK_PENDING";
export const PASS_TURN_DECISION_PENDING_ERROR_CODE = "PASS_TURN_DECISION_PENDING";
export const PASS_TURN_RECKLESS_CHALLENGE_REQUIRED_ERROR_CODE =
  "PASS_TURN_RECKLESS_CHALLENGE_REQUIRED";
export const PASS_TURN_MUST_QUEST_REQUIRED_ERROR_CODE = "PASS_TURN_MUST_QUEST_REQUIRED";
export const PASS_TURN_NOT_ACTIVE_PLAYER_ERROR_CODE = "PASS_TURN_NOT_ACTIVE_PLAYER";

export type AdvanceTurnResult = {
  previousPlayer: PlayerId;
  nextPlayer: PlayerId;
  turnNumber: number;
};

function resolveTurnPlayer(ctx: PassTurnIntentContext): PlayerId | undefined {
  return resolveTurnOwnerId(ctx.framework.state, ctx.G);
}

function getCheapPassTurnFailure(ctx: PassTurnIntentContext): PassTurnFailure | null {
  const activePlayer = resolveTurnPlayer(ctx);
  if (!activePlayer || ctx.playerId !== activePlayer) {
    return {
      valid: false,
      error: "Only the active player can pass the turn",
      errorCode: PASS_TURN_NOT_ACTIVE_PLAYER_ERROR_CODE,
    };
  }

  if (
    ctx.G.pendingTurnTransition ||
    hasPendingBagItems(ctx) ||
    ctx.framework.state.priority.pendingChoice ||
    (ctx.G.pendingEffects?.length ?? 0) > 0
  ) {
    return {
      valid: false,
      error: "Cannot pass turn while a player decision is pending",
      errorCode: PASS_TURN_DECISION_PENDING_ERROR_CODE,
    };
  }

  if (ctx.framework.state.priority.stackDepth > 0) {
    return {
      valid: false,
      error: "Cannot pass turn while stack has unresolved effects",
      errorCode: PASS_TURN_STACK_PENDING_ERROR_CODE,
    };
  }

  return null;
}

function cleanupTemporaryShiftCardsAtEndOfTurn(
  ctx: PassTurnExecutionContext,
  playerId: PlayerId,
): void {
  const turn = ctx.framework.state.status.turn ?? 1;
  const playCards = ctx.framework.zones.getCards({ zone: "play", playerId }) as CardInstanceId[];
  let changed = false;

  for (const cardId of playCards) {
    const meta = ctx.cards.getMeta(String(cardId)) as LorcanaCardMeta | undefined;
    if (
      typeof meta?.temporaryShiftReturnTurn !== "number" ||
      meta.temporaryShiftReturnTurn > turn ||
      !Array.isArray(meta.cardsUnder) ||
      meta.cardsUnder.length === 0
    ) {
      continue;
    }

    const ownerId = (ctx.framework.zones.getCardOwner(cardId) as PlayerId | undefined) ?? playerId;
    detachTemporaryShiftTopCard(ctx, cardId, ownerId);
    changed = true;
  }

  if (changed) {
    invalidateStaticEffects(ctx);
  }
}

function pruneExpiredTemporaryCardMeta(ctx: PassTurnExecutionContext, currentTurn: number): void {
  const cardMetaEntries = ctx.cards.entriesMeta();
  for (const [cardId, rawMeta] of cardMetaEntries) {
    const currentMeta = (rawMeta ?? {}) as LorcanaCardMeta;
    const prunedMeta = pruneExpiredTemporaryEffects(currentMeta, currentTurn);
    if (!prunedMeta || prunedMeta === currentMeta) {
      continue;
    }

    ctx.cards.setMeta(cardId as CardInstanceId, prunedMeta as Record<string, unknown>);
  }
}

function clearInkwellRevealsForAllPlayers(
  ctx: PassTurnExecutionContext,
  players: PlayerId[],
): void {
  for (const playerId of players) {
    // respectExpiry: true keeps stateID-based reveals (e.g. freshly inked cards)
    // alive until they naturally expire, so both players can see what was inked.
    ctx.framework.zones.clearRevealsByZone({ zone: "inkwell", playerId }, { respectExpiry: true });
  }
}

function clearHandRevealsForPlayer(ctx: PassTurnExecutionContext, playerId: PlayerId): void {
  ctx.framework.zones.clearRevealsByZone({ zone: "hand", playerId });
  const handCards = ctx.framework.zones.getCards({ zone: "hand", playerId }) as CardInstanceId[];
  for (const cardId of handCards) {
    const meta = (ctx.cards.require(cardId).meta ?? {}) as LorcanaCardMeta;
    if (meta.revealed) {
      ctx.cards.patchMeta(cardId, { revealed: undefined });
    }
  }
}

function clearActivatedAbilityUsageMeta(ctx: PassTurnExecutionContext, playerId: PlayerId): void {
  const cardsInPlay = ctx.framework.zones.getCards({ zone: "play", playerId }) as CardInstanceId[];
  for (const cardId of cardsInPlay) {
    const currentMeta = (ctx.cards.require(cardId).meta ?? {}) as LorcanaCardMeta;
    if (!currentMeta.activatedAbilityUses && !currentMeta.activatedAbilityUseTurns) {
      continue;
    }
    ctx.cards.patchMeta(cardId, {
      activatedAbilityUses: undefined,
      activatedAbilityUseTurns: undefined,
    });
  }
}

function readyCardsForPlayer(
  ctx: PassTurnExecutionContext,
  playerId: PlayerId,
  currentTurn: number,
): boolean {
  const registry = getOrBuildMoveRegistry(ctx);
  const readyOnlyOneCharacter = hasTemporaryPlayerRestriction(
    ctx.G.temporaryPlayerRestrictions,
    playerId,
    currentTurn,
    "ready-only-one-character",
  );
  const readyRestrictionPayload =
    ctx.G.temporaryPlayerRestrictions.payloadsByPlayer?.[playerId]?.["ready-only-one-character"];
  const readyRestrictionSourceId = readyRestrictionPayload?.sourceId;
  const playCards = ctx.framework.zones.getCards({ zone: "play", playerId }) as CardInstanceId[];
  const canReadyAtStartOfTurn = (cardId: CardInstanceId): boolean => {
    const currentMeta = (ctx.cards.require(cardId).meta ?? {}) as LorcanaCardMeta;
    const atLocationId = currentMeta.atLocationId;
    const isCardAtLocation = !!atLocationId && isCardInPlayZone(ctx, atLocationId as string);
    return (
      currentMeta.state === "exerted" &&
      !hasTemporaryRestriction(currentMeta, currentTurn, "cant-ready", {
        isSourceInPlay: (sourceId) => isCardInPlayZone(ctx, sourceId),
        isCardAtLocation,
      }) &&
      !hasTemporaryRestriction(currentMeta, currentTurn, "cant-ready-at-start-of-turn", {
        isSourceInPlay: (sourceId) => isCardInPlayZone(ctx, sourceId),
        isCardAtLocation,
      }) &&
      !hasStaticCardRestriction({
        state: ctx.framework.state,
        cardId,
        restriction: "cant-ready-at-start-of-turn",
        registry,
      }) &&
      !hasTemporaryRestriction(currentMeta, currentTurn, "doesnt-ready", {
        isSourceInPlay: (sourceId) => isCardInPlayZone(ctx, sourceId),
        isCardAtLocation,
      }) &&
      !hasStaticCardRestriction({
        state: ctx.framework.state,
        cardId,
        restriction: "cant-ready",
        registry,
      })
    );
  };
  const readyCandidates = readyOnlyOneCharacter ? playCards.filter(canReadyAtStartOfTurn) : [];
  const requiresReadyChoice = readyCandidates.length > 1 && readyRestrictionSourceId !== undefined;
  let charactersReadied = 0;

  const playerZoneRefs = [
    { zone: "play", playerId },
    { zone: "inkwell", playerId },
  ] as const;

  for (const zone of playerZoneRefs) {
    const cards = ctx.framework.zones.getCards(zone) as CardInstanceId[];
    const clearDrying = zone.zone === "play";

    for (const cardId of cards) {
      const currentMeta = (ctx.cards.require(cardId).meta ?? {}) as LorcanaCardMeta;
      const nextMeta = { ...currentMeta } as Record<string, unknown>;
      const cantReady = !canReadyAtStartOfTurn(cardId);
      const exceedsReadyLimit =
        zone.zone === "play" &&
        readyOnlyOneCharacter &&
        (requiresReadyChoice || charactersReadied >= 1);

      if (currentMeta.state === "exerted" && !cantReady && !exceedsReadyLimit) {
        nextMeta.state = "ready";
        if (zone.zone === "play") {
          charactersReadied += 1;
        }
        emitTriggeredLorcanaEvent(
          ctx,
          "cardReadied",
          { cardId, source: "start-of-turn", zone: zone.zone },
          { event: "ready", playerId, subjectCardId: cardId },
        );
      }

      if (clearDrying) {
        delete nextMeta.isDrying;
      }

      ctx.cards.setMeta(cardId, nextMeta);
    }
  }

  if (!requiresReadyChoice || !readyRestrictionSourceId) {
    return false;
  }

  const sourceCard = ctx.cards.require(readyRestrictionSourceId);
  const sourceControllerId = sourceCard.controllerID as PlayerId | undefined;
  const sourceDefinition = sourceCard.definition;
  if (!sourceControllerId || !sourceDefinition) {
    return false;
  }

  const effect = {
    type: "ready" as const,
    target: {
      selector: "chosen" as const,
      count: 1 as const,
      owner: "any" as const,
      zones: ["play" as const],
      cardTypes: ["character" as const],
      filter: [{ type: "exerted" as const }],
    },
  };
  const selectionContext: ResolutionSelectionContext = {
    origin: "pending-effect",
    requestId: "pending-start-of-turn-ready",
    kind: "target-selection",
    sourceCardId: readyRestrictionSourceId,
    chooserId: playerId,
    currentSelection: {},
    submitField: "targets",
    targetDsl: [effect.target],
    cardCandidateIds: readyCandidates,
    playerCandidateIds: [],
    allowedZones: ["play"],
    minSelections: 1,
    maxSelections: 1,
    declaredMaxSelections: 1,
    ordered: false,
    autoRejected: false,
    promptLabel: "Choose a character to ready",
  };
  const pendingEffect = createPendingActionEffect(ctx, {
    kind: "target-selection",
    sourceCardId: readyRestrictionSourceId,
    controllerId: sourceControllerId,
    chooserId: playerId,
    cardPlayed: {
      playerId: sourceControllerId,
      cardId: readyRestrictionSourceId,
      cardType: sourceDefinition.cardType,
      costType: "free",
    },
    effect,
    resolutionInput: {},
    selectionContext,
  });
  enqueuePendingActionEffect(ctx, pendingEffect);
  return true;
}

function drawForTurn(ctx: PassTurnExecutionContext, playerId: PlayerId, turnNumber: number): void {
  const openingTurnPlayer = ctx.framework.state.status.otp as PlayerId | undefined;
  const shouldSkipOpeningDraw = turnNumber === 1 && playerId === openingTurnPlayer;
  if (shouldSkipOpeningDraw) {
    return;
  }

  const drawnCards = ctx.framework.zones.drawCards({
    from: { zone: "deck", playerId },
    to: { zone: "hand", playerId },
    count: 1,
  });
  const drawnCardIds = Array.isArray(drawnCards) ? (drawnCards as CardInstanceId[]) : [];

  // Emit triggered events for each drawn card so "Whenever you draw" abilities fire.
  // source: "mandatory-draw" routes these to the turnStart log instead of the current move's outcomes.
  for (const cardId of drawnCardIds) {
    recordCardDrawnThisTurn(ctx, playerId);
    const drawCount =
      (ctx.G.turnMetadata?.cardsDrawnThisTurnByPlayer as Record<string, number> | undefined)?.[
        playerId
      ] ?? 1;
    emitTriggeredLorcanaEvent(
      ctx,
      "cardsDrawn",
      { playerId, amount: 1, cardIds: [cardId], source: "mandatory-draw" },
      {
        event: "draw",
        playerId,
        subjectCardId: cardId,
        eventSnapshot: { drawCountForPlayerThisTurn: drawCount },
      },
    );
  }
}

function shouldSkipDrawStepForPlayer(
  ctx: PassTurnExecutionContext,
  playerId: PlayerId,
  turnNumber: number,
): boolean {
  const openingTurnPlayer = ctx.framework.state.status.otp as PlayerId | undefined;
  if (turnNumber === 1 && playerId === openingTurnPlayer) {
    return true;
  }

  const currentTurn = ctx.framework.state.status.turn ?? turnNumber;
  if (
    hasTemporaryPlayerRestriction(
      ctx.G.temporaryPlayerRestrictions,
      playerId,
      currentTurn,
      "skip-draw-step",
    )
  ) {
    return true;
  }

  const registry = getOrBuildMoveRegistry(ctx);
  return hasStaticPlayerRestriction({
    state: ctx.framework.state,
    playerId,
    restriction: "skip-draw-step",
    registry,
  });
}

function gainLoreFromLocations(ctx: PassTurnExecutionContext, playerId: PlayerId): void {
  const cardsInPlay = ctx.framework.zones.getCards({ zone: "play", playerId }) as CardInstanceId[];
  let locationCount = 0;
  const registry = getOrBuildMoveRegistry(ctx);
  const state = createProjectionState(ctx.framework.state, ctx.G);
  const getDefinition = (id: CardInstanceId) => ctx.cards.getDefinition(id);
  const loreGain = cardsInPlay.reduce((total, cardId) => {
    const definition = ctx.cards.require(cardId).definition;
    if (!definition || !isLocation(definition)) {
      return total;
    }

    locationCount++;
    return total + deriveLore(definition, state, cardId, getDefinition, registry);
  }, 0);

  if (loreGain <= 0) {
    return;
  }

  ctx.framework.log(
    createLorcanaLogProjection(
      "lorcana.outcome.locationLoreGained",
      { playerId, amount: loreGain, locationCount },
      { mode: "PUBLIC" },
      "rules",
    ),
  );

  gainLore(ctx, playerId, loreGain);
}

function getOpponents(ctx: PassTurnExecutionContext, playerId: PlayerId): PlayerId[] {
  return (Object.keys(ctx.G.lore) as PlayerId[]).filter((candidate) => candidate !== playerId);
}

export function advanceTurnToNextPlayer(ctx: PassTurnExecutionContext): AdvanceTurnResult {
  const players = Object.keys(ctx.G.lore) as PlayerId[];
  // Use pendingTurnTransition.previousPlayer when available — finalizeResolutionBoundary
  // transfers priority to the bag resolver, which may be a different player than the one
  // who ended their turn, so ctx.framework.state.currentPlayer (= priority.holder) is
  // unreliable here when the turn advance happens after bag resolution.
  const previousPlayer = (ctx.G.pendingTurnTransition?.previousPlayer ??
    resolveTurnOwnerId(ctx.framework.state, ctx.G)) as PlayerId;
  const currentIndex = players.indexOf(previousPlayer as PlayerId);
  const nextIndex = (currentIndex + 1) % players.length;
  const nextPlayer = players[nextIndex];

  // Update turn and priority
  ctx.framework.status.patch({ turnOwnerId: nextPlayer });
  // Invalidate the static-effect registry: turn-conditional abilities (e.g. "during your turn")
  // depend on turnOwnerId, which just changed. The cache keys on staticEffectsVersion, so we must
  // bump it here or the previous player's turn-conditional keywords will bleed into the next turn.
  invalidateStaticEffects(ctx);
  ctx.framework.priority.setHolder(nextPlayer);
  const turnNumber = ctx.framework.status.incrementTurn();

  // Reset phase to beginning
  ctx.framework.status.setPhase("beginning");
  ctx.framework.priority.openWindow(nextPlayer);

  const readyChoicePending = readyCardsForPlayer(ctx, nextPlayer, turnNumber);
  cleanupExpiredEffects(ctx, turnNumber);
  cleanupDanglingTargetEffects(ctx);
  pruneExpiredTemporaryCardMeta(ctx, turnNumber);
  pruneExpiredTriggerRegistrations(ctx.G, turnNumber);
  pruneExpiredReplacementEffects(ctx.G, turnNumber);
  clearActivatedAbilityUsageMeta(ctx, previousPlayer as PlayerId);
  clearHandRevealsForPlayer(ctx, previousPlayer as PlayerId);
  clearInkwellRevealsForAllPlayers(ctx, players);
  ctx.G.temporaryPlayerRestrictions = pruneExpiredTemporaryPlayerRestrictions(
    ctx.G.temporaryPlayerRestrictions,
    turnNumber,
  ) ?? {
    restrictionsByPlayer: {},
    startsByPlayer: {},
  };
  pruneExpiredPlayFromUnderPermissions(ctx.G.playFromUnderPermissions, turnNumber);
  pruneExpiredPlayFromDiscardPermissions(ctx.G.playFromDiscardPermissions, turnNumber);

  const turnsCompletedByPlayer =
    ctx.G.turnsCompletedByPlayer ?? (ctx.G.turnsCompletedByPlayer = {} as Record<PlayerId, number>);
  turnsCompletedByPlayer[previousPlayer] = (turnsCompletedByPlayer[previousPlayer] ?? 0) + 1;

  // Reset turn metadata (inkedThisTurn is array; ink refills via cardMeta ready in beginning phase)
  ctx.G.turnMetadata = {
    cardsPlayedThisTurn: [],
    charactersQuesting: [],
    inkedThisTurn: [],
    cardsPutIntoInkwellThisTurn: [],
    additionalInkwellActions: 0,
    shiftPlayedThisTurn: [],
    challengesByPlayerThisTurn: {},
    damagedCharactersByOwnerThisTurn: {},
    damageRemovedByPlayerThisTurn: {},
    challengedCharactersThisTurn: [],
    banishedCharactersThisTurn: [],
    banishedCharactersInChallengeByOwnerThisTurn: {},
    discardCardsLeftThisTurn: 0,
    cardsPutIntoDiscardThisTurnByOwner: {},
    pendingCostReductionsByPlayer: {},
    cardsDrawnThisTurnByPlayer: {},
    inkDropsGainedThisTurn: {},
    inkDropsRemovedThisTurn: {},
  };

  // Expired keywords/stat effects can remove static Willpower bonuses (§1.8.1.4).
  invalidateStaticEffects(ctx);
  sweepLethalDamageInPlay(ctx);

  gainLoreFromLocations(ctx, nextPlayer);

  ctx.framework.events.emit({
    kind: "TURN_STARTED",
    playerId: nextPlayer,
    turn: turnNumber,
    phase: "beginning",
  });

  if (readyChoicePending) {
    ctx.framework.priority.setHolder(nextPlayer);
  }

  return { previousPlayer: previousPlayer as PlayerId, nextPlayer, turnNumber };
}

function createPendingTurnTransitionState(
  previousPlayer: PlayerId,
  stage: PendingTurnTransitionState["stage"],
  patch: Partial<PendingTurnTransitionState> = {},
): PendingTurnTransitionState {
  return {
    previousPlayer,
    stage,
    ...patch,
  };
}

function stopTurnTransitionForGameEnd(ctx: PassTurnExecutionContext): boolean {
  if (!ctx.framework.state.status.gameEnded && !checkLoreWinCondition(ctx.G)) return false;
  ctx.G.pendingTurnTransition = undefined;
  return true;
}

export function continuePendingTurnTransition(ctx: PassTurnExecutionContext): void {
  let transitionState = ctx.G.pendingTurnTransition;
  if (!transitionState) {
    return;
  }

  const maxTransitionSteps = 10;
  for (let step = 0; transitionState && step < maxTransitionSteps; step += 1) {
    // An end-turn ability can win the game before the turn itself ends.
    if (stopTurnTransitionForGameEnd(ctx)) return;
    switch (transitionState.stage) {
      case "end-of-turn": {
        ctx.framework.status.setPhase("end");

        if (!transitionState.triggerWindowQueued) {
          openWindow(ctx, {
            window: "end-of-turn",
            playerId: transitionState.previousPlayer,
          });
          finalizeResolutionBoundary(ctx, {
            playerId: transitionState.previousPlayer,
            window: "end-of-turn",
          });
          transitionState = {
            ...transitionState,
            triggerWindowQueued: true,
          };
          ctx.G.pendingTurnTransition = transitionState;
          if (
            hasPendingBagItems(ctx) ||
            ctx.framework.state.priority.pendingChoice ||
            (ctx.G.pendingEffects?.length ?? 0) > 0
          ) {
            return;
          }
        }

        if (stopTurnTransitionForGameEnd(ctx)) return;

        if (!transitionState.statModifiersExpired) {
          cleanupTemporaryShiftCardsAtEndOfTurn(ctx, transitionState.previousPlayer);
          cleanupEndOfTurnStatModifiers(ctx, ctx.framework.state.status.turn ?? 1);
          transitionState = { ...transitionState, statModifiersExpired: true };
          ctx.G.pendingTurnTransition = transitionState;
          invalidateStaticEffects(ctx);
          sweepLethalDamageInPlay(ctx);
          finalizeResolutionBoundary(ctx, {
            playerId: transitionState.previousPlayer,
            window: "end-of-turn",
          });
        }
        if (
          hasPendingBagItems(ctx) ||
          ctx.framework.state.priority.pendingChoice ||
          (ctx.G.pendingEffects?.length ?? 0) > 0
        )
          return;

        if (stopTurnTransitionForGameEnd(ctx)) return;

        // CR 3.4.1.1–3.4.2: finish end-turn abilities and stat expiry before deck loss.
        if (checkDeckEmptyForPlayer(ctx, transitionState.previousPlayer)) {
          const losingPlayer = transitionState.previousPlayer;
          ctx.G.pendingTurnTransition = undefined;
          ctx.framework.events.endGame({
            winner: getOpponents(ctx, losingPlayer)[0],
            reason: `${losingPlayer} ended their turn with no cards in their deck`,
          });
          return;
        }

        transitionState = createPendingTurnTransitionState(
          transitionState.previousPlayer,
          "advance-turn",
        );
        ctx.G.pendingTurnTransition = transitionState;
        continue;
      }

      case "advance-turn": {
        const { previousPlayer, nextPlayer, turnNumber } = advanceTurnToNextPlayer(ctx);
        emitTriggeredLorcanaEvent(ctx, "turnPassed", {
          previousPlayer,
          newPlayer: nextPlayer,
        });

        transitionState = createPendingTurnTransitionState(previousPlayer, "start-of-turn", {
          nextPlayer,
          turnNumber,
        });
        ctx.G.pendingTurnTransition = transitionState;
        if (ctx.framework.state.priority.pendingChoice || (ctx.G.pendingEffects?.length ?? 0) > 0) {
          return;
        }
        continue;
      }

      case "start-of-turn": {
        const nextPlayer = transitionState.nextPlayer;
        if (!nextPlayer) {
          ctx.G.pendingTurnTransition = undefined;
          return;
        }

        if (!transitionState.triggerWindowQueued) {
          openWindow(ctx, {
            window: "start-of-turn",
            playerId: nextPlayer,
          });
          finalizeResolutionBoundary(ctx, {
            playerId: nextPlayer,
            window: "start-of-turn",
          });
          transitionState = {
            ...transitionState,
            triggerWindowQueued: true,
          };
          ctx.G.pendingTurnTransition = transitionState;
          if (hasPendingBagItems(ctx) || ctx.framework.state.priority.pendingChoice) {
            return;
          }
        }

        const turnNumber = transitionState.turnNumber ?? ctx.framework.state.status.turn ?? 1;

        // Sub-step 2: perform the draw and emit triggered events (only once)
        if (!transitionState.drawStepStarted) {
          // Ensure nextPlayer holds priority for the draw step. The start-of-turn
          // trigger window (finalizeResolutionBoundary above) can transfer priority
          // to a bag resolver, leaving priority.holder pointing at the previous
          // player when the draw event is evaluated. "during-turn, whose: opponent"
          // restrictions in triggerMatchesEvent read ctx.framework.state.currentPlayer
          // (== priority.holder), so they would see the wrong active player and
          // fail to fire abilities like Diablo's CIRCLE FAR AND WIDE.
          ctx.framework.priority.setHolder(nextPlayer);
          transitionState = {
            ...transitionState,
            drawStepStarted: true,
          };
          ctx.G.pendingTurnTransition = transitionState;
          if (shouldSkipDrawStepForPlayer(ctx, nextPlayer, turnNumber)) {
            ctx.framework.status.setPhase("main");
            ctx.G.pendingTurnTransition = undefined;
            return;
          }

          drawForTurn(ctx, nextPlayer, turnNumber);

          // Finalize to flush any draw-triggered events (e.g. "Whenever you draw") into the bag
          finalizeResolutionBoundary(ctx, {
            playerId: nextPlayer,
            window: "start-of-turn",
          });
          ctx.G.pendingTurnTransition = transitionState;
          if (
            hasPendingBagItems(ctx) ||
            ctx.framework.state.priority.pendingChoice ||
            (ctx.G.pendingEffects?.length ?? 0) > 0
          ) {
            return;
          }
        }

        // All draw-triggered effects resolved; transition to main phase.
        // Restore priority to the turn player in case bag-effect resolution
        // handed it to an opponent-controlled bag resolver (e.g. Diablo drawing
        // a card for themselves while P2 draws during their start-of-turn).
        ctx.framework.priority.setHolder(nextPlayer);
        ctx.framework.status.setPhase("main");
        ctx.G.pendingTurnTransition = undefined;
        return;
      }
    }
  }

  if (transitionState) {
    throw new Error(
      `Exceeded ${maxTransitionSteps} turn transition steps while resolving pending turn state '${transitionState.stage}'.`,
    );
  }
}

function getPassTurnFailure(ctx: PassTurnIntentContext): PassTurnFailure | null {
  const cheapFailure = getCheapPassTurnFailure(ctx);
  if (cheapFailure) {
    return cheapFailure;
  }

  const registry = getOrBuildMoveRegistry(ctx);
  const recklessAttackerCanChallenge = getEligibleChallengeAttackers(ctx).some((attackerId) => {
    const attackerDef = ctx.cards.getDefinition(attackerId);
    const hasStaticReckless = attackerDef ? hasKeyword(attackerDef, "Reckless") : false;
    const attackerMeta = ctx.cards.require(attackerId).meta;
    const currentTurn = ctx.framework.state.status.turn ?? 1;
    const controllerId = ctx.cards.require(attackerId).controllerID as PlayerId | undefined;
    const controllerCantChallenge =
      controllerId !== undefined &&
      (hasTemporaryPlayerRestriction(
        ctx.G.temporaryPlayerRestrictions,
        controllerId,
        currentTurn,
        "cant-challenge",
      ) ||
        hasStaticPlayerRestriction({
          state: ctx.framework.state,
          playerId: controllerId,
          restriction: "cant-challenge",
          registry,
        }));
    if (controllerCantChallenge) {
      return false;
    }

    return hasStaticReckless || hasTemporaryKeyword(attackerMeta, currentTurn, "Reckless");
  });

  if (recklessAttackerCanChallenge) {
    return {
      valid: false,
      error: "A Reckless character must challenge if able",
      errorCode: PASS_TURN_RECKLESS_CHALLENGE_REQUIRED_ERROR_CODE,
    };
  }

  // "Must quest if able" enforcement (e.g. This Growing Pressure, Cobra Bubbles
  // — Dedicated Official, Ariel — Curious Traveler). A character under the
  // `must-quest` restriction that is still a legal quester blocks
  // their controller from passing turn.
  const currentTurn = ctx.framework.state.status.turn ?? 1;
  const eligibleQuesters = getEligibleQuestCharacters(ctx);
  const mustQuestCharacterPending = eligibleQuesters.some((cardId) => {
    const meta = ctx.cards.require(cardId).meta;
    return (
      hasTemporaryRestriction(meta, currentTurn, "must-quest") ||
      hasStaticCardRestriction({
        state: ctx.framework.state,
        cardId,
        restriction: "must-quest",
        registry,
      })
    );
  });
  const adventurousCanQuest = eligibleQuesters.some(cardId => {
    const card = ctx.cards.require(cardId);
    const definition = ctx.cards.getDefinition(cardId);
    const meta = card.meta ?? {};
    const lost = hasTemporaryLostKeyword(meta, currentTurn, "Adventurous") ||
      (registry.byTarget.get(cardId) ?? []).some(entry => entry.kind === "lose-keyword" && entry.payload.keyword === "Adventurous");
    return !lost && ((definition && hasKeyword(definition, "Adventurous")) ||
      hasTemporaryKeyword(meta, currentTurn, "Adventurous") ||
      (registry.byTarget.get(cardId) ?? []).some(entry =>
        entry.kind === "gain-keyword" && entry.payload.keyword === "Adventurous"));
  });
  if (adventurousCanQuest) {
    return { valid: false, error: "Adventurous must quest if able", errorCode: "PASS_TURN_ADVENTUROUS_QUEST_REQUIRED" };
  }
  if (mustQuestCharacterPending) {
    return {
      valid: false,
      error: "A character under the must-quest restriction must quest if able",
      errorCode: PASS_TURN_MUST_QUEST_REQUIRED_ERROR_CODE,
    };
  }

  return null;
}

/**
 * Pass turn to next player
 */
export const passTurn: LorcanaMoveDefinition<"passTurn"> = {
  optimistic: true,
  validate: (ctx): RuntimeValidationResult => getPassTurnFailure(ctx) ?? { valid: true },

  execute: (ctx) => {
    const currentPlayer = ctx.playerId as PlayerId;
    ctx.framework.log(
      createLorcanaLogProjection(
        "lorcana.move.passTurn",
        {
          playerId: currentPlayer,
        },
        { mode: "PUBLIC" },
        "action",
      ),
    );

    ctx.G.pendingTurnTransition = createPendingTurnTransitionState(currentPlayer, "end-of-turn");
    continuePendingTurnTransition(ctx);
  },

  available: (ctx) => !getPassTurnFailure(ctx),
};

patches.before:
/**
 * Lorcana Runtime State Types
 *
 * New state types for the MatchRuntime architecture.
 * Uses MatchState<G> = { G, ctx } pattern where:
 * - G: game-specific state (LorcanaG)
 * - ctx: framework-managed runtime state (TCGCtx)
 */

import type {
  Amount,
  Classification,
  Condition,
  Effect,
  ReplacementAbilityKind,
  ReplacementRegistrationKind,
  Trigger,
} from "@tcg/lorcana-types";
import type { CardInstanceId, MatchState, PlayerId } from "#core";
import type { CardPlayedPayload, DynamicAmountEventSnapshot } from "./domain-events";
import type { ResolutionSelectionContext } from "./resolution-selection";
import type { SlottedTargetInput } from "../targeting/slotted-targets";

// Re-export MatchState for convenience
export type { MatchState };

/**
 * Card State (Ready/Exerted)
 */
export type CardReadyState = "ready" | "exerted";

/**
 * Lorcana Phase
 *
 * Three-phase turn structure (Rule 4.1.1):
 * - beginning: Ready, Set, Draw steps
 * - main: Player can take turn actions
 * - end: End of turn cleanup
 */
export type LorcanaPhase = "beginning" | "main" | "end";

/**
 * Turn Step (within Beginning phase)
 */
export type LorcanaStep = "ready" | "set" | "draw";

/**
 * Challenge State
 *
 * Temporary state during challenge resolution.
 */
export interface ChallengeState {
  attacker: CardInstanceId;
  defender: CardInstanceId;
  attackerOwnerId: PlayerId;
  defenderOwnerId: PlayerId;
  stage: "declaration" | "damage" | "post-damage";
}

/**
 * Supported continuous-effect stat keys.
 * Keep this union broad enough for future stat-mod effect coverage.
 */
export type ContinuousEffectStat =
  | "strength"
  | "willpower"
  | "lore"
  | "moveCost"
  | "singer-threshold";

/**
 * Continuous effect instance for stat modifiers.
 * Additional effect kinds can be added to the union as runtime support expands.
 */
export interface StatModifierContinuousEffectInstance {
  id: string;
  kind: "stat-modifier";
  sourceId: CardInstanceId;
  targetId: CardInstanceId;
  controllerId?: PlayerId;
  stat: ContinuousEffectStat;
  modifier: number;
  condition?: Condition;
  duration: "this-turn" | "until-start-of-next-turn";
  createdAtTurn: number;
  expiresAtTurn: number;
  nonStacking?: boolean;
}

/**
 * Continuous effect instances tracked in runtime state.
 * Currently stat-modifier focused; future kinds should extend this union.
 */
export type ContinuousEffectInstance = StatModifierContinuousEffectInstance;

/**
 * Continuous effect runtime state
 */
export interface ContinuousEffectState {
  /** Monotonic sequence for deterministic effect IDs */
  nextSeq: number;
  instances: ContinuousEffectInstance[];
  /** Secondary index: stat-modifier instances keyed by target card for O(1) lookup */
  byTarget: Record<CardInstanceId, StatModifierContinuousEffectInstance[]>;
}

/**
 * Turn Metadata
 *
 * Tracks actions taken this turn for validation and cleanup.
 * Ink available is derived from ctx.framework.zones (Option B: count of ready cards in inkwell).
 */
export interface TurnMetadata {
  cardsPlayedThisTurn: CardInstanceId[];
  charactersQuesting: CardInstanceId[];
  /** Card instance IDs inked this turn (one per turn by default; supports "second inkwell" effects) */
  inkedThisTurn: CardInstanceId[];
  /** Card instance IDs put into any inkwell this turn, including effect-based moves */
  cardsPutIntoInkwellThisTurn: CardInstanceId[];
  /** Additional hand-to-inkwell actions allowed for the active player this turn */
  additionalInkwellActions?: number;
  /** Top cards that were played using Shift this turn */
  shiftPlayedThisTurn: CardInstanceId[];
  /** Challenge declarations by player this turn */
  challengesByPlayerThisTurn: Record<PlayerId, number>;
  /** Characters that took damage this turn, grouped by owner */
  damagedCharactersByOwnerThisTurn: Record<PlayerId, number>;
  /** Total damage removed from characters this turn, grouped by the player who caused the heal */
  damageRemovedByPlayerThisTurn: Record<PlayerId, number>;
  /** Character instance IDs that were challenged this turn */
  challengedCharactersThisTurn: CardInstanceId[];
  /** Character instance IDs banished this turn */
  banishedCharactersThisTurn: CardInstanceId[];
  /** Characters banished in a challenge this turn, grouped by owner */
  banishedCharactersInChallengeByOwnerThisTurn: Record<PlayerId, number>;
  /** Number of cards that left any discard pile this turn */
  discardCardsLeftThisTurn: number;
  /** Number of cards that were put into a discard pile this turn, grouped by owner */
  cardsPutIntoDiscardThisTurnByOwner: Record<PlayerId, number>;
  /** Pending temporary play-cost reductions keyed by controller */
  pendingCostReductionsByPlayer: Record<PlayerId, PendingCostReduction[]>;
  /** Cards drawn this turn, counted per player (for Ink Amplifier and similar) */
  cardsDrawnThisTurnByPlayer: Record<PlayerId, number>;
  /** Ink drops gained this turn, counted per player ("unless you got an ink drop this turn") */
  inkDropsGainedThisTurn: Record<PlayerId, number>;
  /** Ink drops removed this turn, counted per player ("whenever you remove an ink drop" metrics) */
  inkDropsRemovedThisTurn: Record<PlayerId, number>;
  /** Cards put under a character this turn, keyed by the character's instance ID */
  cardsUnderThisTurn?: Record<CardInstanceId, CardInstanceId[]>;
}

export interface PendingCostReduction {
  amount: number;
  sourceId?: CardInstanceId;
  cardType?:
    | "character"
    | "item"
    | "location"
    | "action"
    | "song"
    | ("character" | "item" | "location" | "action" | "song")[]
    | readonly ("character" | "item" | "location" | "action" | "song")[];
  classification?: Classification | Classification[] | readonly Classification[];
  cardName?: string;
  playMethod?: "shift" | "standard" | "either";
  expiresAtTurn: number;
  consumeOnUse: boolean;
}

/**
 * Temporary permission to play a card from under a specific item this turn.
 * Created by "RISE AND JOIN ME!" style effects.
 */
export interface PlayFromUnderPermission {
  /** The item whose cards may be played */
  sourceItemId: CardInstanceId;
  /** Which turn this expires at (end-of-turn cleanup) */
  expiresAtTurn: number;
  /** If set, only cards of this type may be played (e.g. "character") */
  cardType?: string;
  /** The player who activated the effect (only their cards should be playable) */
  controllerId: PlayerId;
}

/**
 * Player-level continuous effect state for play-from-under permissions.
 * Tracked at the `LorcanaG` level (not turnMetadata) so permissions are
 * managed via expiry-based cleanup alongside other continuous effects.
 */
export interface PlayFromUnderPermissionsState {
  permissionsByPlayer: Record<PlayerId, PlayFromUnderPermission[]>;
}

/**
 * Temporary permission to play a specific card from discard this turn.
 */
export interface PlayFromDiscardPermission {
  cardId: CardInstanceId;
  expiresAtTurn: number;
  cardType?: string;
  controllerId: PlayerId;
  /** Cards played via this permission enter play exerted (Remember Me). */
  entersExerted?: boolean;
  /** When true, the permission covers every card matching cardType (player-wide). */
  allCards?: boolean;
  /**
   * Unique-by-name mode (Remember Me): each card played via this permission
   * records its name here, and further plays of a recorded name are refused.
   */
  uniqueByName?: boolean;
  playedNames?: readonly string[];
}

export interface PlayFromDiscardPermissionsState {
  permissionsByPlayer: Record<PlayerId, PlayFromDiscardPermission[]>;
}

export interface TemporaryGrantedAbilityPayload {
  type: string;
  [key: string]: unknown;
}

export interface TemporaryRestrictionPayload {
  type: string;
  sourceId?: CardInstanceId;
  activeWhileSourceInPlay?: boolean;
  duration?: unknown;
  /**
   * A condition that must be met for the restriction to be active.
   * When present, the restriction is only enforced while the condition evaluates to true.
   * For example, `{ type: "not", condition: { type: "at-location" } }` means
   * the restriction is inactive when the card is at a location.
   */
  condition?: { type: string; [key: string]: unknown };
}

export interface TemporaryKeywordPayload {
  type: string;
  sourceId?: CardInstanceId;
  activeWhileSourceInPlay?: boolean;
  duration?: unknown;
}

export interface TemporaryPlayerRestrictionPayload {
  type: string;
  sourceId?: CardInstanceId;
  activeWhileSourceInPlay?: boolean;
  duration?: unknown;
}

export type BufferedTriggeredEvent =
  | "play"
  | "sing"
  | "discard"
  | "draw"
  | "quest"
  | "ready"
  | "support"
  | "move"
  | "challenge"
  | "challenged"
  | "challenged-and-banished"
  | "banish"
  | "banish-in-challenge"
  | "remove-damage"
  | "return-to-hand"
  | "ink"
  | "start-turn"
  | "end-turn"
  | "be-chosen"
  | "boost"
  | "put-card-under"
  | "damage"
  | "deal-damage"
  | "exert"
  | "gain-lore"
  | "lose-lore"
  | "ink-drop-gained"
  | "ink-drop-removed"
  | "leave-discard";

export interface PendingTriggeredEvent {
  id: string;
  event: BufferedTriggeredEvent;
  playerId?: PlayerId;
  cardPlayed?: CardPlayedPayload;
  fromZone?: string;
  toZone?: string;
  subjectCardId?: CardInstanceId;
  triggerSourceCardId?: CardInstanceId;
  /** The card type of the source that caused this event (e.g., "action", "item") */
  sourceCardType?: "character" | "action" | "item" | "location";
  attackerId?: CardInstanceId;
  defenderId?: CardInstanceId;
  happenedInChallenge?: boolean;
  eventSnapshot?: DynamicAmountEventSnapshot;
  triggerCandidates?: TriggeredEventCandidate[];
}

export interface GeneratedTriggeredAbilityEntry {
  id: string;
  type: "generated-triggered-ability";
  controllerId: PlayerId;
  sourceId: CardInstanceId;
  cardPlayed: CardPlayedPayload;
  ability: {
    name?: string;
    trigger: Trigger;
    condition?: Condition;
    effect: Effect;
  };
  startsAtTurn: number;
  expiresAtTurn: number;
}

export interface BagEffectEntry {
  id: string;
  type: "bag-effect";
  kind: "triggered-ability";
  abilityId: string;
  abilityIndex?: number;
  abilityKey: string;
  abilityName?: string;
  /** Copied from printed/generated triggered ability when present */
  autoResolve?: boolean;
  controllerId: PlayerId;
  chooserId: PlayerId;
  sourceId: CardInstanceId;
  cardPlayed: CardPlayedPayload;
  /** The play-event payload that fired this trigger (the played card, e.g. the
   * song for "whenever you play a song" abilities). Condition evaluation at
   * resolution uses this so "that card"-scoped conditions see the subject. */
  eventCardPlayed?: CardPlayedPayload;
  trigger?: Trigger;
  condition?: Condition;
  effect: Effect;
  occurrenceIndex: number;
  resolutionInput: PendingActionResolutionInput;
}

export interface BagState {
  nextSeq: number;
  items: BagEffectEntry[];
  lastResolvedPlayerId?: PlayerId;
}

export type DelayedTriggerTiming = "end-of-turn" | "start-of-next-turn" | "end-of-next-turn";

export type DelayedTriggerWindow = "end-of-turn" | "start-of-turn";

export interface TriggerRegistrationAbility {
  id?: string;
  name?: string;
  trigger: Trigger;
  sourceZones?: ("play" | "hand" | "discard" | "inkwell")[];
  condition?: Condition;
  effect: Effect;
  autoResolve?: boolean;
}

export interface TriggeredEventCandidate {
  abilityId: string;
  abilityIndex?: number;
  controllerId: PlayerId;
  sourceId: CardInstanceId;
  cardPlayed: CardPlayedPayload;
  ability: TriggerRegistrationAbility;
  resolutionInput: PendingActionResolutionInput;
}

export type TriggerRegistrationLifecycle =
  | {
      kind: "floating";
      startsAtTurn: number;
      expiresAtTurn: number;
    }
  | {
      kind: "delayed";
      timing: DelayedTriggerTiming;
      dueWindow: DelayedTriggerWindow;
      duePlayerId: PlayerId;
      dueCompletedTurns: number;
    };

export interface TriggerRegistration {
  id: string;
  abilityId: string;
  abilityIndex?: number;
  sourceId: CardInstanceId;
  controllerId: PlayerId;
  cardPlayed: CardPlayedPayload;
  ability: TriggerRegistrationAbility;
  lifecycle: TriggerRegistrationLifecycle;
  resolutionInput: PendingActionResolutionInput;
}

export interface TriggeredAbilitiesUsageLedger {
  occurrences: Record<string, number>;
  resolutions: Record<string, number>;
  /** Distinguishes repeated plays of one physical card for limited-use triggers. */
  sourceLifetimes?: Record<string, number>;
}

export interface TriggeredAbilitiesState {
  pendingEvents: PendingTriggeredEvent[];
  registrations: TriggerRegistration[];
  bag: BagState;
  usageLedger: TriggeredAbilitiesUsageLedger;
}

export type ReplacementEventKind =
  | "modify-stat"
  | "deal-damage"
  | "put-damage"
  | "remove-damage"
  | "challenge-damage"
  | "gain-lore"
  | "zone-change";

export interface ReplacementTriggerContext {
  playerId?: PlayerId;
  subjectCardId?: CardInstanceId;
  triggerSourceCardId?: CardInstanceId;
  attackerId?: CardInstanceId;
  defenderId?: CardInstanceId;
}

export interface ReplacementRegistration {
  id: string;
  sourceId: CardInstanceId;
  controllerId: PlayerId;
  replacement: ReplacementRegistrationKind;
  targetId?: CardInstanceId;
  createdAtTurn: number;
  startsAtTurn: number;
  expiresAtTurn: number;
}

export interface ReplacementUsageLedger {
  perTurn: Record<string, number>;
}

export interface ReplacementEffectsState {
  nextSeq: number;
  registrations: ReplacementRegistration[];
  usageLedger: ReplacementUsageLedger;
  /** Secondary index: registration IDs keyed by event kind for O(1) lookup */
  byEventKind: Record<string, string[]>;
}

export type PendingTurnTransitionStage = "end-of-turn" | "advance-turn" | "start-of-turn";

export interface PendingTurnTransitionState {
  previousPlayer: PlayerId;
  stage: PendingTurnTransitionStage;
  nextPlayer?: PlayerId;
  turnNumber?: number;
  triggerWindowQueued?: boolean;
  /** Turn-end stat expiry and its resulting banishments have already been processed. */
  statModifiersExpired?: boolean;
  drawStepStarted?: boolean;
}

export interface TemporaryPlayerRestrictionsState {
  restrictionsByPlayer: Record<PlayerId, Record<string, number>>;
  startsByPlayer: Record<PlayerId, Record<string, number>>;
  payloadsByPlayer?: Record<PlayerId, Record<string, TemporaryPlayerRestrictionPayload>>;
}

export type PendingActionEffectKind =
  | "discard-choice"
  | "choice-selection"
  | "name-card-selection"
  | "optional-selection"
  | "scry-selection"
  | "target-selection";

export interface PendingActionEffectContinuation {
  remainingEffects?: unknown[];
  stagedSequence?: {
    sequenceEffect: unknown;
    collectedTargets: Array<CardInstanceId | PlayerId>;
    collectedTargetCounts: number[];
    remainingSteps: unknown[];
  };
}

export interface PendingActionResolutionInput {
  targets?: CardInstanceId | PlayerId | readonly (CardInstanceId | PlayerId)[];
  /**
   * Structured selections for multi-slot effects. Populated at the move input
   * boundary (e.g. `resolveEffect`) when the caller passes a
   * {@link SlottedTargetInput}. See `targeting/slotted-targets.ts`.
   */
  slottedTargets?: SlottedTargetInput;
  currentTargets?: CardInstanceId | PlayerId | readonly (CardInstanceId | PlayerId)[];
  contextTargets?: CardInstanceId | PlayerId | readonly (CardInstanceId | PlayerId)[];
  targetSelectionResolved?: boolean;
  amount?: Amount;
  namedCard?: string;
  resolveOptional?: boolean;
  enterPlayExerted?: boolean;
  choiceIndex?: number;
  preventAutoResolveTriggeredEffects?: boolean;
  destinations?: {
    zone: string;
    cards: CardInstanceId | CardInstanceId[];
  }[];
  eventSnapshot?: DynamicAmountEventSnapshot;
  triggerContext?: ReplacementTriggerContext;
  /**
   * Player whose choice is currently being resolved for optional effects where
   * the chooser differs from the source controller. Defaults such as play-card
   * source zones should prefer this value when no explicit target player exists.
   */
  chooserPlayerId?: PlayerId;
}

export interface PendingActionEffect {
  /** Retains the exact limited-use trigger through suspended choices. */
  bagUsage?: Pick<BagEffectEntry, "id" | "abilityKey" | "trigger">;
  id: string;
  type: "action-effect";
  kind: PendingActionEffectKind;
  abilityIndex?: number;
  sourceId: CardInstanceId;
  sourceCardId: CardInstanceId;
  controllerId: PlayerId;
  chooserId: PlayerId;
  cardPlayed: CardPlayedPayload;
  effect: unknown;
  continuation?: PendingActionEffectContinuation;
  resolutionInput: PendingActionResolutionInput;
  selectionContext?: ResolutionSelectionContext;
  /** Propagates {@link ActionEffectResolutionOptions.allowSuspendWithZeroTargetCandidates} for resolve-effect continuations. */
  allowSuspendWithZeroTargetCandidates?: boolean;
}

/**
 * Lorcana Card Metadata (Dynamic State)
 *
 * Stored in ctx.framework.zones.private.cardMeta
 * Values are optional to optimize memory usage, defaults must be the undefined type.
 */
export interface LorcanaCardMeta extends Record<string, unknown> {
  /** CR 6.7.6: Strength immediately before this instance last left play. */
  lastKnownStrength?: number;
  /** Ready or exerted */
  state?: CardReadyState;
  /** Damage counters */
  damage?: number;
  /** Drying = summoning sickness */
  isDrying?: boolean;
  /** Public face state for cards that can stay visible in an otherwise face-down zone */
  publicFaceState?: "faceUp" | "faceDown";
  /** Location this character is at (if any) */
  atLocationId?: CardInstanceId;
  /** IDs of cards stacked under this top card (Shift stack) */
  cardsUnder?: CardInstanceId[];
  /** ID of the card currently on top of this card in a Shift stack */
  stackParentId?: CardInstanceId;
  /** Whether this card entered play using Shift */
  playedViaShift?: boolean;
  /** Whether this shifted top card should detach at the end of its controller's turn */
  temporaryShiftReturnTurn?: number;
  /** Which payment mode was used to play this card */
  playedCostType?: "standard" | "shift" | "sing" | "singTogether" | "free";
  /** Temporary keywords granted by action effects and their inclusive expiration turn */
  temporaryKeywords?: Record<string, number>;
  /** Inclusive start turns for temporary keywords (defaults to current turn when omitted) */
  temporaryKeywordStarts?: Record<string, number>;
  /** Temporary values for parameterized keywords (e.g. Challenger/Resist) */
  temporaryKeywordValues?: Record<string, number>;
  /** Structured payloads for temporary keywords keyed by keyword name */
  temporaryKeywordPayloads?: Record<string, TemporaryKeywordPayload>;
  /** Temporary lost keywords and their inclusive expiration turn */
  temporaryLostKeywords?: Record<string, number>;
  /** Inclusive start turns for temporary lost keywords */
  temporaryLostKeywordStarts?: Record<string, number>;
  /** Temporary classifications granted by action effects and their inclusive expiration turn */
  temporaryClassifications?: Record<string, number>;
  /** Inclusive start turns for temporary classifications */
  temporaryClassificationStarts?: Record<string, number>;
  /** Temporary granted non-keyword abilities and their inclusive expiration turn */
  temporaryAbilities?: Record<string, number>;
  /** Inclusive start turns for temporary non-keyword abilities */
  temporaryAbilityStarts?: Record<string, number>;
  /** Structured payloads for temporary granted abilities keyed by ability id */
  temporaryAbilityPayloads?: Record<string, TemporaryGrantedAbilityPayload>;
  /** Temporary restrictions granted by action effects and their inclusive expiration turn */
  temporaryRestrictions?: Record<string, number>;
  /** Inclusive start turns for temporary restrictions */
  temporaryRestrictionStarts?: Record<string, number>;
  /** Structured payloads for temporary restrictions keyed by restriction id */
  temporaryRestrictionPayloads?: Record<string, TemporaryRestrictionPayload>;
  /** Activated ability usage count keyed by ability id */
  activatedAbilityUses?: Record<string, number>;
  /** Turn number for the current activated ability usage count */
  activatedAbilityUseTurns?: Record<string, number>;
  /** Printed replacement abilities currently active on this card */
  replacementAbilities?: ReplacementAbilityKind[];
  /** Where to send this card when its action effects finish resolving, overriding the default discard */
  afterPlayDestination?: "bottom-of-deck";
}

/**
 * Lorcana Game-Specific State (G)
 *
 * This is the game-owned state that goes in MatchState<G>.
 * Framework manages zones, cards, and ctx. Card definitions from staticResources;
 * ink/character/permanent state derived from ctx.framework.zones and cardMeta; game end from ctx.status.
 */
export interface LorcanaG {
  /** Lore totals for each player (win at 20) */
  lore: Record<PlayerId, number>;

  /**
   * Ink drop counters for each player (Hyperia City).
   * A player may remove an ink drop to pay 1 {I} of any ink cost.
   * Drops persist across turns; they are not ink cards and never enter the inkwell.
   */
  inkDrops: Record<PlayerId, number>;

  /**
   * Override lore required to win for specific players.
   * When a player appears in this map, they need that much lore to win
   * instead of the default 20. Populated by win-condition-modification
   * static abilities (e.g. Donald Duck - Flustered Sorcerer).
   *
   * Keys are the player IDs whose win threshold is raised.
   * The map only contains overrides — missing entries use the default 20.
   */
  loreToWin?: Record<PlayerId, number>;

  /** Turn metadata - reset each turn */
  turnMetadata: TurnMetadata;

  /** Triggered-ability runtime state */
  triggeredAbilities: TriggeredAbilitiesState;

  /** Suspended action-effect resolutions waiting for a player decision */
  pendingEffects: PendingActionEffect[];

  /** Pass-turn pipeline continuation when delayed triggers suspend mid-transition */
  pendingTurnTransition?: PendingTurnTransitionState;

  /** Completed turns per player (persistent across turns) */
  turnsCompletedByPlayer: Record<PlayerId, number>;

  /** Active continuous effects */
  continuousEffects: ContinuousEffectState;

  /** Temporary play restrictions tracked on players rather than cards */
  temporaryPlayerRestrictions: TemporaryPlayerRestrictionsState;

  /** Player-level permissions to play cards from under items (continuous effect) */
  playFromUnderPermissions: PlayFromUnderPermissionsState;

  /** Player-level permissions to play specific cards from discard */
  playFromDiscardPermissions: PlayFromDiscardPermissionsState;

  /** Replacement effects created by resolving cards and abilities */
  replacementEffects: ReplacementEffectsState;

  /** Challenge state (only during challenge) */
  challengeState?: ChallengeState;

  /**
   * Monotonically increasing counter incremented whenever state that affects
   * static ability evaluation changes (cards entering/leaving play, keyword grants,
   * ability grants, continuous effects, card damage/location/exert state).
   * Used by move-registry-cache to skip O(N) registry rebuilds for commands
   * that don't touch static ability inputs (e.g. drawing a card, gaining lore).
   */
  staticEffectsVersion: number;
}

/**
 * Lorcana Match State
 *
 * Full state type: MatchState
 */
export type LorcanaMatchState = MatchState;

/**
 * Create initial Lorcana G state
 */
export function createInitialLorcanaG(
  player1Id: PlayerId,
  player2Id: PlayerId,
  ...additionalPlayerIds: PlayerId[]
): LorcanaG {
  const playerIds = [player1Id, player2Id, ...additionalPlayerIds];
  return {
    lore: Object.fromEntries(playerIds.map((id) => [id, 0])),
    inkDrops: Object.fromEntries(playerIds.map((id) => [id, 0])),
    turnMetadata: {
      cardsPlayedThisTurn: [],
      charactersQuesting: [],
      inkedThisTurn: [],
      cardsPutIntoInkwellThisTurn: [],
      additionalInkwellActions: 0,
      shiftPlayedThisTurn: [],
      challengesByPlayerThisTurn: {},
      damagedCharactersByOwnerThisTurn: {},
      damageRemovedByPlayerThisTurn: {},
      challengedCharactersThisTurn: [],
      banishedCharactersThisTurn: [],
      banishedCharactersInChallengeByOwnerThisTurn: {},
      discardCardsLeftThisTurn: 0,
      cardsPutIntoDiscardThisTurnByOwner: {},
      pendingCostReductionsByPlayer: {},
      cardsDrawnThisTurnByPlayer: {} as Record<PlayerId, number>,
      inkDropsGainedThisTurn: {} as Record<PlayerId, number>,
      inkDropsRemovedThisTurn: {} as Record<PlayerId, number>,
    },
    triggeredAbilities: {
      pendingEvents: [],
      registrations: [],
      bag: {
        nextSeq: 1,
        items: [],
      },
      usageLedger: {
        occurrences: {},
        resolutions: {},
      },
    },
    pendingEffects: [],
    turnsCompletedByPlayer: Object.fromEntries(playerIds.map((id) => [id, 0])),
    continuousEffects: {
      nextSeq: 1,
      instances: [],
      byTarget: {},
    },
    temporaryPlayerRestrictions: {
      restrictionsByPlayer: {},
      startsByPlayer: {},
      payloadsByPlayer: {},
    },
    playFromUnderPermissions: {
      permissionsByPlayer: {},
    },
    playFromDiscardPermissions: {
      permissionsByPlayer: {},
    },
    replacementEffects: {
      nextSeq: 1,
      registrations: [],
      usageLedger: {
        perTurn: {},
      },
      byEventKind: {},
    },
    staticEffectsVersion: 0,
  };
}

/**
 * Create default card metadata for new cards entering play
 */
export function createDefaultCardMeta(): LorcanaCardMeta {
  return {
    damage: undefined,
    isDrying: undefined,
    publicFaceState: undefined,
    state: undefined,
    atLocationId: undefined,
    cardsUnder: undefined,
    stackParentId: undefined,
    playedViaShift: undefined,
    playedCostType: undefined,
    temporaryKeywords: undefined,
    temporaryKeywordStarts: undefined,
    temporaryKeywordValues: undefined,
    temporaryAbilities: undefined,
    temporaryAbilityStarts: undefined,
    temporaryAbilityPayloads: undefined,
    temporaryRestrictions: undefined,
    temporaryRestrictionPayloads: undefined,
    temporaryRestrictionStarts: undefined,
    activatedAbilityUses: undefined,
    activatedAbilityUseTurns: undefined,
    replacementAbilities: undefined,
  };
}

patches.after:
/**
 * Lorcana Runtime State Types
 *
 * New state types for the MatchRuntime architecture.
 * Uses MatchState<G> = { G, ctx } pattern where:
 * - G: game-specific state (LorcanaG)
 * - ctx: framework-managed runtime state (TCGCtx)
 */

import type {
  Amount,
  Classification,
  Condition,
  Effect,
  ReplacementAbilityKind,
  ReplacementRegistrationKind,
  Trigger,
} from "@tcg/lorcana-types";
import type { CardInstanceId, MatchState, PlayerId } from "#core";
import type { CardPlayedPayload, DynamicAmountEventSnapshot } from "./domain-events";
import type { ResolutionSelectionContext } from "./resolution-selection";
import type { SlottedTargetInput } from "../targeting/slotted-targets";

// Re-export MatchState for convenience
export type { MatchState };

/**
 * Card State (Ready/Exerted)
 */
export type CardReadyState = "ready" | "exerted";

/**
 * Lorcana Phase
 *
 * Three-phase turn structure (Rule 4.1.1):
 * - beginning: Ready, Set, Draw steps
 * - main: Player can take turn actions
 * - end: End of turn cleanup
 */
export type LorcanaPhase = "beginning" | "main" | "end";

/**
 * Turn Step (within Beginning phase)
 */
export type LorcanaStep = "ready" | "set" | "draw";

/**
 * Challenge State
 *
 * Temporary state during challenge resolution.
 */
export interface ChallengeState {
  attacker: CardInstanceId;
  defender: CardInstanceId;
  attackerOwnerId: PlayerId;
  defenderOwnerId: PlayerId;
  stage: "declaration" | "damage" | "post-damage";
}

/**
 * Supported continuous-effect stat keys.
 * Keep this union broad enough for future stat-mod effect coverage.
 */
export type ContinuousEffectStat =
  | "strength"
  | "willpower"
  | "lore"
  | "moveCost"
  | "singer-threshold";

/**
 * Continuous effect instance for stat modifiers.
 * Additional effect kinds can be added to the union as runtime support expands.
 */
export interface StatModifierContinuousEffectInstance {
  id: string;
  kind: "stat-modifier";
  sourceId: CardInstanceId;
  targetId: CardInstanceId;
  controllerId?: PlayerId;
  stat: ContinuousEffectStat;
  modifier: number;
  condition?: Condition;
  duration: "this-turn" | "until-start-of-next-turn";
  createdAtTurn: number;
  expiresAtTurn: number;
  nonStacking?: boolean;
}

/**
 * Continuous effect instances tracked in runtime state.
 * Currently stat-modifier focused; future kinds should extend this union.
 */
export type ContinuousEffectInstance = StatModifierContinuousEffectInstance;

/**
 * Continuous effect runtime state
 */
export interface ContinuousEffectState {
  /** Monotonic sequence for deterministic effect IDs */
  nextSeq: number;
  instances: ContinuousEffectInstance[];
  /** Secondary index: stat-modifier instances keyed by target card for O(1) lookup */
  byTarget: Record<CardInstanceId, StatModifierContinuousEffectInstance[]>;
}

/**
 * Turn Metadata
 *
 * Tracks actions taken this turn for validation and cleanup.
 * Ink available is derived from ctx.framework.zones (Option B: count of ready cards in inkwell).
 */
export interface TurnMetadata {
  cardsPlayedThisTurn: CardInstanceId[];
  charactersQuesting: CardInstanceId[];
  /** Card instance IDs inked this turn (one per turn by default; supports "second inkwell" effects) */
  inkedThisTurn: CardInstanceId[];
  /** Card instance IDs put into any inkwell this turn, including effect-based moves */
  cardsPutIntoInkwellThisTurn: CardInstanceId[];
  /** Additional hand-to-inkwell actions allowed for the active player this turn */
  additionalInkwellActions?: number;
  /** Top cards that were played using Shift this turn */
  shiftPlayedThisTurn: CardInstanceId[];
  /** Challenge declarations by player this turn */
  challengesByPlayerThisTurn: Record<PlayerId, number>;
  /** Characters that took damage this turn, grouped by owner */
  damagedCharactersByOwnerThisTurn: Record<PlayerId, number>;
  /** Total damage removed from characters this turn, grouped by the player who caused the heal */
  damageRemovedByPlayerThisTurn: Record<PlayerId, number>;
  /** Character instance IDs that were challenged this turn */
  challengedCharactersThisTurn: CardInstanceId[];
  /** Character instance IDs banished this turn */
  banishedCharactersThisTurn: CardInstanceId[];
  /** Characters banished in a challenge this turn, grouped by owner */
  banishedCharactersInChallengeByOwnerThisTurn: Record<PlayerId, number>;
  /** Number of cards that left any discard pile this turn */
  discardCardsLeftThisTurn: number;
  /** Number of cards that were put into a discard pile this turn, grouped by owner */
  cardsPutIntoDiscardThisTurnByOwner: Record<PlayerId, number>;
  /** Pending temporary play-cost reductions keyed by controller */
  pendingCostReductionsByPlayer: Record<PlayerId, PendingCostReduction[]>;
  /** Cards drawn this turn, counted per player (for Ink Amplifier and similar) */
  cardsDrawnThisTurnByPlayer: Record<PlayerId, number>;
  /** Ink drops gained this turn, counted per player ("unless you got an ink drop this turn") */
  inkDropsGainedThisTurn: Record<PlayerId, number>;
  /** Ink drops removed this turn, counted per player ("whenever you remove an ink drop" metrics) */
  inkDropsRemovedThisTurn: Record<PlayerId, number>;
  /** Cards put under a character this turn, keyed by the character's instance ID */
  cardsUnderThisTurn?: Record<CardInstanceId, CardInstanceId[]>;
}

export interface PendingCostReduction {
  amount: number;
  sourceId?: CardInstanceId;
  cardType?:
    | "character"
    | "item"
    | "location"
    | "action"
    | "song"
    | ("character" | "item" | "location" | "action" | "song")[]
    | readonly ("character" | "item" | "location" | "action" | "song")[];
  classification?: Classification | Classification[] | readonly Classification[];
  cardName?: string;
  playMethod?: "shift" | "standard" | "either";
  expiresAtTurn: number;
  consumeOnUse: boolean;
}

/**
 * Temporary permission to play a card from under a specific item this turn.
 * Created by "RISE AND JOIN ME!" style effects.
 */
export interface PlayFromUnderPermission {
  /** The item whose cards may be played */
  sourceItemId: CardInstanceId;
  /** Which turn this expires at (end-of-turn cleanup) */
  expiresAtTurn: number;
  /** If set, only cards of this type may be played (e.g. "character") */
  cardType?: string;
  /** The player who activated the effect (only their cards should be playable) */
  controllerId: PlayerId;
}

/**
 * Player-level continuous effect state for play-from-under permissions.
 * Tracked at the `LorcanaG` level (not turnMetadata) so permissions are
 * managed via expiry-based cleanup alongside other continuous effects.
 */
export interface PlayFromUnderPermissionsState {
  permissionsByPlayer: Record<PlayerId, PlayFromUnderPermission[]>;
}

/**
 * Temporary permission to play a specific card from discard this turn.
 */
export interface PlayFromDiscardPermission {
  cardId: CardInstanceId;
  expiresAtTurn: number;
  cardType?: string;
  controllerId: PlayerId;
  /** Cards played via this permission enter play exerted (Remember Me). */
  entersExerted?: boolean;
  /** When true, the permission covers every card matching cardType (player-wide). */
  allCards?: boolean;
  /**
   * Unique-by-name mode (Remember Me): each card played via this permission
   * records its name here, and further plays of a recorded name are refused.
   */
  uniqueByName?: boolean;
  playedNames?: readonly string[];
}

export interface PlayFromDiscardPermissionsState {
  permissionsByPlayer: Record<PlayerId, PlayFromDiscardPermission[]>;
}

export interface TemporaryGrantedAbilityPayload {
  type: string;
  [key: string]: unknown;
}

export interface TemporaryRestrictionPayload {
  type: string;
  sourceId?: CardInstanceId;
  activeWhileSourceInPlay?: boolean;
  duration?: unknown;
  /**
   * A condition that must be met for the restriction to be active.
   * When present, the restriction is only enforced while the condition evaluates to true.
   * For example, `{ type: "not", condition: { type: "at-location" } }` means
   * the restriction is inactive when the card is at a location.
   */
  condition?: { type: string; [key: string]: unknown };
}

export interface TemporaryKeywordPayload {
  type: string;
  sourceId?: CardInstanceId;
  activeWhileSourceInPlay?: boolean;
  duration?: unknown;
}

export interface TemporaryPlayerRestrictionPayload {
  type: string;
  sourceId?: CardInstanceId;
  activeWhileSourceInPlay?: boolean;
  duration?: unknown;
}

export type BufferedTriggeredEvent =
  | "play"
  | "sing"
  | "discard"
  | "draw"
  | "quest"
  | "ready"
  | "support"
  | "move"
  | "challenge"
  | "challenged"
  | "challenged-and-banished"
  | "banish"
  | "banish-in-challenge"
  | "remove-damage"
  | "return-to-hand"
  | "ink"
  | "start-turn"
  | "end-turn"
  | "be-chosen"
  | "boost"
  | "put-card-under"
  | "damage"
  | "deal-damage"
  | "exert"
  | "gain-lore"
  | "lose-lore"
  | "ink-drop-gained"
  | "ink-drop-removed"
  | "leave-discard";

export interface PendingTriggeredEvent {
  id: string;
  event: BufferedTriggeredEvent;
  playerId?: PlayerId;
  cardPlayed?: CardPlayedPayload;
  fromZone?: string;
  toZone?: string;
  subjectCardId?: CardInstanceId;
  triggerSourceCardId?: CardInstanceId;
  /** The card type of the source that caused this event (e.g., "action", "item") */
  sourceCardType?: "character" | "action" | "item" | "location";
  attackerId?: CardInstanceId;
  defenderId?: CardInstanceId;
  happenedInChallenge?: boolean;
  eventSnapshot?: DynamicAmountEventSnapshot;
  triggerCandidates?: TriggeredEventCandidate[];
}

export interface GeneratedTriggeredAbilityEntry {
  id: string;
  type: "generated-triggered-ability";
  controllerId: PlayerId;
  sourceId: CardInstanceId;
  cardPlayed: CardPlayedPayload;
  ability: {
    name?: string;
    trigger: Trigger;
    condition?: Condition;
    effect: Effect;
  };
  startsAtTurn: number;
  expiresAtTurn: number;
}

export interface BagEffectEntry {
  id: string;
  type: "bag-effect";
  kind: "triggered-ability";
  abilityId: string;
  abilityIndex?: number;
  abilityKey: string;
  abilityName?: string;
  /** Copied from printed/generated triggered ability when present */
  autoResolve?: boolean;
  controllerId: PlayerId;
  chooserId: PlayerId;
  sourceId: CardInstanceId;
  cardPlayed: CardPlayedPayload;
  /** The play-event payload that fired this trigger (the played card, e.g. the
   * song for "whenever you play a song" abilities). Condition evaluation at
   * resolution uses this so "that card"-scoped conditions see the subject. */
  eventCardPlayed?: CardPlayedPayload;
  trigger?: Trigger;
  condition?: Condition;
  effect: Effect;
  occurrenceIndex: number;
  resolutionInput: PendingActionResolutionInput;
}

export interface BagState {
  nextSeq: number;
  items: BagEffectEntry[];
  lastResolvedPlayerId?: PlayerId;
}

export type DelayedTriggerTiming = "end-of-turn" | "start-of-next-turn" | "end-of-next-turn";

export type DelayedTriggerWindow = "end-of-turn" | "start-of-turn";

export interface TriggerRegistrationAbility {
  id?: string;
  name?: string;
  trigger: Trigger;
  sourceZones?: ("play" | "hand" | "discard" | "inkwell")[];
  condition?: Condition;
  effect: Effect;
  autoResolve?: boolean;
}

export interface TriggeredEventCandidate {
  abilityId: string;
  abilityIndex?: number;
  controllerId: PlayerId;
  sourceId: CardInstanceId;
  cardPlayed: CardPlayedPayload;
  ability: TriggerRegistrationAbility;
  resolutionInput: PendingActionResolutionInput;
}

export type TriggerRegistrationLifecycle =
  | {
      kind: "floating";
      startsAtTurn: number;
      expiresAtTurn: number;
    }
  | {
      kind: "delayed";
      timing: DelayedTriggerTiming;
      dueWindow: DelayedTriggerWindow;
      duePlayerId: PlayerId;
      dueCompletedTurns: number;
    };

export interface TriggerRegistration {
  id: string;
  abilityId: string;
  abilityIndex?: number;
  sourceId: CardInstanceId;
  controllerId: PlayerId;
  cardPlayed: CardPlayedPayload;
  ability: TriggerRegistrationAbility;
  lifecycle: TriggerRegistrationLifecycle;
  resolutionInput: PendingActionResolutionInput;
}

export interface TriggeredAbilitiesUsageLedger {
  occurrences: Record<string, number>;
  resolutions: Record<string, number>;
  /** Distinguishes repeated plays of one physical card for limited-use triggers. */
  sourceLifetimes?: Record<string, number>;
}

export interface TriggeredAbilitiesState {
  pendingEvents: PendingTriggeredEvent[];
  registrations: TriggerRegistration[];
  bag: BagState;
  usageLedger: TriggeredAbilitiesUsageLedger;
}

export type ReplacementEventKind =
  | "modify-stat"
  | "deal-damage"
  | "put-damage"
  | "remove-damage"
  | "challenge-damage"
  | "gain-lore"
  | "zone-change";

export interface ReplacementTriggerContext {
  playerId?: PlayerId;
  subjectCardId?: CardInstanceId;
  triggerSourceCardId?: CardInstanceId;
  attackerId?: CardInstanceId;
  defenderId?: CardInstanceId;
}

export interface ReplacementRegistration {
  id: string;
  sourceId: CardInstanceId;
  controllerId: PlayerId;
  replacement: ReplacementRegistrationKind;
  targetId?: CardInstanceId;
  createdAtTurn: number;
  startsAtTurn: number;
  expiresAtTurn: number;
}

export interface ReplacementUsageLedger {
  perTurn: Record<string, number>;
}

export interface ReplacementEffectsState {
  nextSeq: number;
  registrations: ReplacementRegistration[];
  usageLedger: ReplacementUsageLedger;
  /** Secondary index: registration IDs keyed by event kind for O(1) lookup */
  byEventKind: Record<string, string[]>;
}

export type PendingTurnTransitionStage = "end-of-turn" | "advance-turn" | "start-of-turn";

export interface PendingTurnTransitionState {
  previousPlayer: PlayerId;
  stage: PendingTurnTransitionStage;
  nextPlayer?: PlayerId;
  turnNumber?: number;
  triggerWindowQueued?: boolean;
  /** Turn-end stat expiry and its resulting banishments have already been processed. */
  statModifiersExpired?: boolean;
  drawStepStarted?: boolean;
}

export interface TemporaryPlayerRestrictionsState {
  restrictionsByPlayer: Record<PlayerId, Record<string, number>>;
  startsByPlayer: Record<PlayerId, Record<string, number>>;
  payloadsByPlayer?: Record<PlayerId, Record<string, TemporaryPlayerRestrictionPayload>>;
}

export type PendingActionEffectKind =
  | "discard-choice"
  | "choice-selection"
  | "name-card-selection"
  | "optional-selection"
  | "scry-selection"
  | "target-selection";

export interface PendingActionEffectContinuation {
  remainingEffects?: unknown[];
  stagedSequence?: {
    sequenceEffect: unknown;
    collectedTargets: Array<CardInstanceId | PlayerId>;
    collectedTargetCounts: number[];
    remainingSteps: unknown[];
  };
}

export interface PendingActionResolutionInput {
  effectInkDropCounters?: number[];
  targets?: CardInstanceId | PlayerId | readonly (CardInstanceId | PlayerId)[];
  /**
   * Structured selections for multi-slot effects. Populated at the move input
   * boundary (e.g. `resolveEffect`) when the caller passes a
   * {@link SlottedTargetInput}. See `targeting/slotted-targets.ts`.
   */
  slottedTargets?: SlottedTargetInput;
  currentTargets?: CardInstanceId | PlayerId | readonly (CardInstanceId | PlayerId)[];
  contextTargets?: CardInstanceId | PlayerId | readonly (CardInstanceId | PlayerId)[];
  targetSelectionResolved?: boolean;
  amount?: Amount;
  namedCard?: string;
  resolveOptional?: boolean;
  enterPlayExerted?: boolean;
  choiceIndex?: number;
  preventAutoResolveTriggeredEffects?: boolean;
  destinations?: {
    zone: string;
    cards: CardInstanceId | CardInstanceId[];
  }[];
  eventSnapshot?: DynamicAmountEventSnapshot;
  triggerContext?: ReplacementTriggerContext;
  /**
   * Player whose choice is currently being resolved for optional effects where
   * the chooser differs from the source controller. Defaults such as play-card
   * source zones should prefer this value when no explicit target player exists.
   */
  chooserPlayerId?: PlayerId;
}

export interface PendingActionEffect {
  /** Retains the exact limited-use trigger through suspended choices. */
  bagUsage?: Pick<BagEffectEntry, "id" | "abilityKey" | "trigger">;
  id: string;
  type: "action-effect";
  kind: PendingActionEffectKind;
  abilityIndex?: number;
  sourceId: CardInstanceId;
  sourceCardId: CardInstanceId;
  controllerId: PlayerId;
  chooserId: PlayerId;
  cardPlayed: CardPlayedPayload;
  effect: unknown;
  continuation?: PendingActionEffectContinuation;
  resolutionInput: PendingActionResolutionInput;
  selectionContext?: ResolutionSelectionContext;
  /** Propagates {@link ActionEffectResolutionOptions.allowSuspendWithZeroTargetCandidates} for resolve-effect continuations. */
  allowSuspendWithZeroTargetCandidates?: boolean;
}

/**
 * Lorcana Card Metadata (Dynamic State)
 *
 * Stored in ctx.framework.zones.private.cardMeta
 * Values are optional to optimize memory usage, defaults must be the undefined type.
 */
export interface LorcanaCardMeta extends Record<string, unknown> {
  /** CR 6.7.6: Strength immediately before this instance last left play. */
  lastKnownStrength?: number;
  /** Ready or exerted */
  state?: CardReadyState;
  /** Damage counters */
  damage?: number;
  /** Drying = summoning sickness */
  isDrying?: boolean;
  /** Public face state for cards that can stay visible in an otherwise face-down zone */
  publicFaceState?: "faceUp" | "faceDown";
  /** Location this character is at (if any) */
  atLocationId?: CardInstanceId;
  /** IDs of cards stacked under this top card (Shift stack) */
  cardsUnder?: CardInstanceId[];
  /** ID of the card currently on top of this card in a Shift stack */
  stackParentId?: CardInstanceId;
  /** Whether this card entered play using Shift */
  playedViaShift?: boolean;
  /** Whether this shifted top card should detach at the end of its controller's turn */
  temporaryShiftReturnTurn?: number;
  /** Which payment mode was used to play this card */
  playedCostType?: "standard" | "shift" | "sing" | "singTogether" | "free";
  /** Temporary keywords granted by action effects and their inclusive expiration turn */
  temporaryKeywords?: Record<string, number>;
  /** Inclusive start turns for temporary keywords (defaults to current turn when omitted) */
  temporaryKeywordStarts?: Record<string, number>;
  /** Temporary values for parameterized keywords (e.g. Challenger/Resist) */
  temporaryKeywordValues?: Record<string, number>;
  /** Structured payloads for temporary keywords keyed by keyword name */
  temporaryKeywordPayloads?: Record<string, TemporaryKeywordPayload>;
  /** Temporary lost keywords and their inclusive expiration turn */
  temporaryLostKeywords?: Record<string, number>;
  /** Inclusive start turns for temporary lost keywords */
  temporaryLostKeywordStarts?: Record<string, number>;
  /** Temporary classifications granted by action effects and their inclusive expiration turn */
  temporaryClassifications?: Record<string, number>;
  /** Inclusive start turns for temporary classifications */
  temporaryClassificationStarts?: Record<string, number>;
  /** Temporary granted non-keyword abilities and their inclusive expiration turn */
  temporaryAbilities?: Record<string, number>;
  /** Inclusive start turns for temporary non-keyword abilities */
  temporaryAbilityStarts?: Record<string, number>;
  /** Structured payloads for temporary granted abilities keyed by ability id */
  temporaryAbilityPayloads?: Record<string, TemporaryGrantedAbilityPayload>;
  /** Temporary restrictions granted by action effects and their inclusive expiration turn */
  temporaryRestrictions?: Record<string, number>;
  /** Inclusive start turns for temporary restrictions */
  temporaryRestrictionStarts?: Record<string, number>;
  /** Structured payloads for temporary restrictions keyed by restriction id */
  temporaryRestrictionPayloads?: Record<string, TemporaryRestrictionPayload>;
  /** Activated ability usage count keyed by ability id */
  activatedAbilityUses?: Record<string, number>;
  /** Turn number for the current activated ability usage count */
  activatedAbilityUseTurns?: Record<string, number>;
  /** Printed replacement abilities currently active on this card */
  replacementAbilities?: ReplacementAbilityKind[];
  /** Where to send this card when its action effects finish resolving, overriding the default discard */
  afterPlayDestination?: "bottom-of-deck";
}

/**
 * Lorcana Game-Specific State (G)
 *
 * This is the game-owned state that goes in MatchState<G>.
 * Framework manages zones, cards, and ctx. Card definitions from staticResources;
 * ink/character/permanent state derived from ctx.framework.zones and cardMeta; game end from ctx.status.
 */
export interface LorcanaG {
  /** Lore totals for each player (win at 20) */
  lore: Record<PlayerId, number>;

  /** CR2.3 counters outside play; absent in older states means zero. Never card instances or ink. */

  /**
   * Ink drop counters for each player (Hyperia City).
   * A player may remove an ink drop to pay 1 {I} of any ink cost.
   * Drops persist across turns; they are not ink cards and never enter the inkwell.
   */
  inkDrops: Record<PlayerId, number>;

  /**
   * Override lore required to win for specific players.
   * When a player appears in this map, they need that much lore to win
   * instead of the default 20. Populated by win-condition-modification
   * static abilities (e.g. Donald Duck - Flustered Sorcerer).
   *
   * Keys are the player IDs whose win threshold is raised.
   * The map only contains overrides — missing entries use the default 20.
   */
  loreToWin?: Record<PlayerId, number>;

  /** Turn metadata - reset each turn */
  turnMetadata: TurnMetadata;

  /** Triggered-ability runtime state */
  triggeredAbilities: TriggeredAbilitiesState;

  /** Suspended action-effect resolutions waiting for a player decision */
  pendingEffects: PendingActionEffect[];

  /** Pass-turn pipeline continuation when delayed triggers suspend mid-transition */
  pendingTurnTransition?: PendingTurnTransitionState;

  /** Completed turns per player (persistent across turns) */
  turnsCompletedByPlayer: Record<PlayerId, number>;

  /** Active continuous effects */
  continuousEffects: ContinuousEffectState;

  /** Temporary play restrictions tracked on players rather than cards */
  temporaryPlayerRestrictions: TemporaryPlayerRestrictionsState;

  /** Player-level permissions to play cards from under items (continuous effect) */
  playFromUnderPermissions: PlayFromUnderPermissionsState;

  /** Player-level permissions to play specific cards from discard */
  playFromDiscardPermissions: PlayFromDiscardPermissionsState;

  /** Replacement effects created by resolving cards and abilities */
  replacementEffects: ReplacementEffectsState;

  /** Challenge state (only during challenge) */
  challengeState?: ChallengeState;

  /**
   * Monotonically increasing counter incremented whenever state that affects
   * static ability evaluation changes (cards entering/leaving play, keyword grants,
   * ability grants, continuous effects, card damage/location/exert state).
   * Used by move-registry-cache to skip O(N) registry rebuilds for commands
   * that don't touch static ability inputs (e.g. drawing a card, gaining lore).
   */
  staticEffectsVersion: number;
}

/**
 * Lorcana Match State
 *
 * Full state type: MatchState
 */
export type LorcanaMatchState = MatchState;

/**
 * Create initial Lorcana G state
 */
export function createInitialLorcanaG(
  player1Id: PlayerId,
  player2Id: PlayerId,
  ...additionalPlayerIds: PlayerId[]
): LorcanaG {
  const playerIds = [player1Id, player2Id, ...additionalPlayerIds];
  return {
    lore: Object.fromEntries(playerIds.map((id) => [id, 0])),
    inkDrops: Object.fromEntries(playerIds.map((id) => [id, 0])),
    turnMetadata: {
      cardsPlayedThisTurn: [],
      charactersQuesting: [],
      inkedThisTurn: [],
      cardsPutIntoInkwellThisTurn: [],
      additionalInkwellActions: 0,
      shiftPlayedThisTurn: [],
      challengesByPlayerThisTurn: {},
      damagedCharactersByOwnerThisTurn: {},
      damageRemovedByPlayerThisTurn: {},
      challengedCharactersThisTurn: [],
      banishedCharactersThisTurn: [],
      banishedCharactersInChallengeByOwnerThisTurn: {},
      discardCardsLeftThisTurn: 0,
      cardsPutIntoDiscardThisTurnByOwner: {},
      pendingCostReductionsByPlayer: {},
      cardsDrawnThisTurnByPlayer: {} as Record<PlayerId, number>,
      inkDropsGainedThisTurn: {} as Record<PlayerId, number>,
      inkDropsRemovedThisTurn: {} as Record<PlayerId, number>,
    },
    triggeredAbilities: {
      pendingEvents: [],
      registrations: [],
      bag: {
        nextSeq: 1,
        items: [],
      },
      usageLedger: {
        occurrences: {},
        resolutions: {},
      },
    },
    pendingEffects: [],
    turnsCompletedByPlayer: Object.fromEntries(playerIds.map((id) => [id, 0])),
    continuousEffects: {
      nextSeq: 1,
      instances: [],
      byTarget: {},
    },
    temporaryPlayerRestrictions: {
      restrictionsByPlayer: {},
      startsByPlayer: {},
      payloadsByPlayer: {},
    },
    playFromUnderPermissions: {
      permissionsByPlayer: {},
    },
    playFromDiscardPermissions: {
      permissionsByPlayer: {},
    },
    replacementEffects: {
      nextSeq: 1,
      registrations: [],
      usageLedger: {
        perTurn: {},
      },
      byEventKind: {},
    },
    staticEffectsVersion: 0,
  };
}

/**
 * Create default card metadata for new cards entering play
 */
export function createDefaultCardMeta(): LorcanaCardMeta {
  return {
    damage: undefined,
    isDrying: undefined,
    publicFaceState: undefined,
    state: undefined,
    atLocationId: undefined,
    cardsUnder: undefined,
    stackParentId: undefined,
    playedViaShift: undefined,
    playedCostType: undefined,
    temporaryKeywords: undefined,
    temporaryKeywordStarts: undefined,
    temporaryKeywordValues: undefined,
    temporaryAbilities: undefined,
    temporaryAbilityStarts: undefined,
    temporaryAbilityPayloads: undefined,
    temporaryRestrictions: undefined,
    temporaryRestrictionPayloads: undefined,
    temporaryRestrictionStarts: undefined,
    activatedAbilityUses: undefined,
    activatedAbilityUseTurns: undefined,
    replacementAbilities: undefined,
  };
}

