  const requiredCount = getRequiredDiscardCardCostCount(ability);
  if (requiredCount === 0) {
    return [];
  }

  if (ability.cost?.discardChosen === true) {
    return [];
  }

  return getEligibleDiscardCostCards(ctx, currentPlayer, ability).slice(0, requiredCount);
}

