  }

  if (requestedCosts.length !== requiredCount) {
    return createFailure(
      `Ability requires ${requiredCount} discard cost selection${requiredCount === 1 ? "" : "s"}`,
      "ABILITY_COST_SELECTION_MISMATCH",
    );
