      filter.maxCost !== null &&
      (filter.maxCost as { type?: unknown }).type === "chosen-card-cost") ||
    filter.excludeChosenCard === true ||
    filter.sameNameAsChosenCard === true ||
    filter.inEventSnapshotDiscardedCards === true ||
    filter.inEventSnapshotCardsUnder === true
