    statusConfig,
    choosingFirstPlayer,
    players = [],
  } = params;
  return {
    protocolVersion: 1,
    matchID,
    gameID,
    rulesetHash,
    _stateID: 0,
    playerIds: players.map((player) => player.id as PlayerId),
    status: {
      // We start in turn zero
      turn: 0,
      gameEnded: false,
      gameSegment: statusConfig?.initialGameSegment,
      phase: statusConfig?.initialPhase,
      choosingFirstPlayer,
      pendingMulligan: undefined,
