  | "damage-removed-by-player"
  | "discard-cards-left"
  | "discard-cards-entered"
  | "quested-characters"
  | "played-cards"
  | "cards-drawn-by-player"
  | "ink-drops-gained"
  | "ink-drops-removed";

export interface TurnMetricCondition {
