export interface ExertOtherCost {
  type: "exert-other";
  /** What to exert */
  target: "character" | "item";
  /** How many to exert */
  amount?: number;
}

// ============================================================================
// Combined Cost
// ============================================================================

/**
 * Individual cost component
 */
export type CostComponent =
  | ExertCost
  | InkCost
  | BanishCost
  | DiscardCost
  | DamageSelfCost
  | ReturnToHandCost
  | PutUnderCost
  | ExertOtherCost;

/**
 * Complete ability cost - can have multiple components
 *
 * @example "{E}" - just exert
