                amount: normalizedAmount as VariableAmount,
                state,
                controllerId,
                sourceId: cardId,
                getDefinitionByInstanceId,
              })
            : typeof ability.effect.reduction?.ink === "number"
              ? ability.effect.reduction.ink
              : 0;

    return total + Math.max(0, effectAmount);
  }, 0);
}

