    baseWillpower + modifier,
    registry
      ? getStaticStatFloor({
          cardInstanceId,
          stat: "willpower",
          registry,
        })
      : undefined,
  );

  return definition.cardType === "location" ? Math.max(0, derivedWillpower) : derivedWillpower;
}

