  return (
    !state.G.pendingTurnTransition &&
    (state.G.triggeredAbilities?.bag?.items?.length ?? 0) === 0 &&
    !state.ctx.priority.pendingChoice &&
    (state.G.pendingEffects?.length ?? 0) === 0
